<!DOCTYPE html>
<!--
  ============================================================================
  codx-junior — INFRA view mockup
  File: infra.html
  ----------------------------------------------------------------------------
  A fully functional, browser-runnable mockup of the Infrastructure (Docker)
  view. Everything is simulated in-file: no real network calls.

  MOCK boundaries are marked with `// MOCK:` (JS) and  (HTML).

  Open this file directly in a browser (double-click / file://) — no build,
  no server, no npm. First paint uses CDN assets (Tailwind CSS + Font Awesome,
  both version-pinned); if they fail to load the layout still holds because
  the component CSS is plain, self-contained CSS.
  ============================================================================
-->
<html lang="en" data-theme="codx-dark">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Infra — codx-junior</title>

  <!-- 1. Public libs, version pinned -->
  <script src="https://cdn.tailwindcss.com/3.4.1"></script>
  <link rel="stylesheet"
        href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css" />

  <!-- 2. Design tokens (Tailwind config) -->
  <script>
    // MOCK: no build step — Tailwind Play CDN reads this config object.
    tailwind.config = {
      theme: {
        extend: {
          colors: {
            base: {
              100: 'rgb(var(--surface) / <alpha-value>)',
              200: 'rgb(var(--surface-2) / <alpha-value>)',
              300: 'rgb(var(--bg) / <alpha-value>)',
              400: 'rgb(var(--surface-3) / <alpha-value>)'
            },
            content: 'rgb(var(--text) / <alpha-value>)',
            dim: 'rgb(var(--text-dim) / <alpha-value>)',
            muted: 'rgb(var(--text-muted) / <alpha-value>)',
            primary: {
              DEFAULT: 'rgb(var(--primary) / <alpha-value>)',
              light: 'rgb(var(--primary-lt) / <alpha-value>)'
            },
            success: 'rgb(var(--success) / <alpha-value>)',
            warning: 'rgb(var(--warning) / <alpha-value>)',
            error: 'rgb(var(--error) / <alpha-value>)',
            info: 'rgb(var(--info) / <alpha-value>)'
          },
          borderRadius: { md: '10px', lg: '14px' }
        }
      }
    }
  </script>

  <!-- 3. Component CSS (plain CSS → resilient without Tailwind CDN) -->
  <style>
    :root {
      /* codx-junior dark tokens (as RGB triplets for alpha support) */
      --bg: 11 11 13;
      --surface: 22 22 26;
      --surface-2: 31 31 36;
      --surface-3: 41 41 48;
      --text: 244 244 245;
      --text-dim: 161 161 170;
      --text-muted: 113 113 122;
      --primary: 99 102 241;
      --primary-lt: 129 140 248;
      --success: 16 185 129;
      --warning: 245 158 11;
      --error: 239 68 68;
      --info: 56 189 248;
      --line: rgba(255, 255, 255, .08);
      --line-strong: rgba(255, 255, 255, .16);
      --shadow: 0 1px 2px rgba(0, 0, 0, .4), 0 8px 24px rgba(0, 0, 0, .35);
    }

    * { box-sizing: border-box; }
    html, body { height: 100%; }
    body {
      margin: 0;
      background: rgb(var(--bg));
      color: rgb(var(--text));
      font-family: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
      font-size: 14px;
      line-height: 1.5;
      -webkit-font-smoothing: antialiased;
    }
    a { color: inherit; text-decoration: none; }
    button { font: inherit; }
    ::-webkit-scrollbar { width: 10px; height: 10px; }
    ::-webkit-scrollbar-thumb {
      background: rgba(255, 255, 255, .13);
      border-radius: 99px; border: 2px solid transparent; background-clip: content-box;
    }
    ::-webkit-scrollbar-thumb:hover { background: rgba(255, 255, 255, .22); background-clip: content-box; }
    ::-webkit-scrollbar-track { background: transparent; }
    :focus-visible { outline: 2px solid rgb(var(--primary)); outline-offset: 2px; border-radius: 8px; }
    .mono { font-family: "SF Mono", ui-monospace, Menlo, Monaco, Consolas, "Courier New", monospace; }

    /* ---------- layout shell ---------- */
    .app { display: flex; min-height: 100vh; }
    .sidebar {
      width: 248px; flex: 0 0 248px; background: rgb(var(--surface));
      border-right: 1px solid var(--line);
      position: sticky; top: 0; height: 100vh; overflow-y: auto;
    }
    .main { flex: 1 1 auto; min-width: 0; display: flex; flex-direction: column; }
    .topbar {
      height: 56px; border-bottom: 1px solid var(--line);
      display: flex; align-items: center; gap: 12px; padding: 0 18px;
      position: sticky; top: 0; z-index: 20;
      background: rgb(var(--bg) / .88); backdrop-filter: blur(10px);
    }
    .content { padding: 20px 22px 120px; flex: 1 1 auto; min-width: 0; }

    /* ---------- buttons ---------- */
    .btn {
      display: inline-flex; align-items: center; justify-content: center; gap: 7px;
      height: 34px; padding: 0 12px; border-radius: 10px;
      border: 1px solid var(--line); background: rgb(var(--surface-2)); color: rgb(var(--text));
      font-size: 13px; font-weight: 600; white-space: nowrap; cursor: pointer; line-height: 1;
      transition: background .15s, border-color .15s, transform .12s, color .15s;
    }
    .btn:hover { background: rgb(var(--surface-3)); }
    .btn:active { transform: translateY(1px); }
    .btn[disabled], .btn.disabled { opacity: .45; cursor: not-allowed; transform: none; }
    .btn-xs { height: 26px; font-size: 12px; padding: 0 9px; border-radius: 8px; gap: 5px; }
    .btn-sm { height: 30px; font-size: 12.5px; padding: 0 10px; border-radius: 9px; }
    .btn-block { width: 100%; }
    .btn-primary { background: rgb(var(--primary)); border-color: rgb(var(--primary)); color: #fff; }
    .btn-primary:hover { background: rgb(var(--primary-lt)); border-color: rgb(var(--primary-lt)); }
    .btn-ghost { background: transparent; border-color: transparent; color: rgb(var(--text-dim)); }
    .btn-ghost:hover { background: rgb(var(--surface-2)); color: rgb(var(--text)); }
    .btn-outline { background: transparent; }
    .btn-outline:hover { background: rgb(var(--surface-2)); }
    .btn-success { background: rgb(var(--success) / .16); border-color: rgb(var(--success) / .35); color: #6ee7b7; }
    .btn-success:hover { background: rgb(var(--success) / .26); }
    .btn-warning { background: rgb(var(--warning) / .16); border-color: rgb(var(--warning) / .35); color: #fcd34d; }
    .btn-warning:hover { background: rgb(var(--warning) / .26); }
    .btn-error { background: rgb(var(--error) / .14); border-color: rgb(var(--error) / .35); color: #fca5a5; }
    .btn-error:hover { background: rgb(var(--error) / .24); }
    .btn-circle { width: 34px; padding: 0; border-radius: 999px; }
    .btn-xs.btn-circle { width: 26px; }
    .btn-sm.btn-circle { width: 30px; }

    /* ---------- surfaces ---------- */
    .card { background: rgb(var(--surface)); border: 1px solid var(--line); border-radius: 14px; }
    .card-pad { padding: 16px; }
    .line-h { height: 1px; background: var(--line); }
    .divider-v { width: 1px; align-self: stretch; background: var(--line); }

    /* ---------- badges ---------- */
    .badge {
      display: inline-flex; align-items: center; gap: 5px;
      padding: 2px 8px; border-radius: 999px; font-size: 11.5px; font-weight: 600;
      border: 1px solid transparent; white-space: nowrap;
    }
    .badge-xs { font-size: 10.5px; padding: 1px 6px; }
    .badge .dot { width: 6px; height: 6px; border-radius: 99px; background: currentColor; }
    .badge-success { background: rgb(var(--success) / .14); color: #34d399; border-color: rgb(var(--success) / .28); }
    .badge-warning { background: rgb(var(--warning) / .14); color: #fbbf24; border-color: rgb(var(--warning) / .28); }
    .badge-error { background: rgb(var(--error) / .14); color: #f87171; border-color: rgb(var(--error) / .28); }
    .badge-info { background: rgb(var(--info) / .14); color: #38bdf8; border-color: rgb(var(--info) / .28); }
    .badge-primary { background: rgb(var(--primary) / .16); color: #a5b4fc; border-color: rgb(var(--primary) / .32); }
    .badge-neutral { background: rgb(var(--surface-3)); color: rgb(var(--text-dim)); border-color: var(--line); }

    /* ---------- forms ---------- */
    .input, .select {
      height: 34px; width: 100%; background: rgb(var(--surface-2));
      border: 1px solid var(--line); border-radius: 10px; padding: 0 11px;
      color: rgb(var(--text)); font-size: 13px; outline: none;
      transition: border-color .15s, box-shadow .15s;
    }
    .input-sm, .select-sm { height: 30px; font-size: 12.5px; }
    .input:focus, .select:focus { border-color: rgb(var(--primary)); box-shadow: 0 0 0 3px rgb(var(--primary) / .18); }
    .input::placeholder { color: rgb(var(--text-muted)); }
    .select { appearance: none; padding-right: 30px;
      background-image: linear-gradient(45deg, transparent 50%, rgb(var(--text-muted)) 50%), linear-gradient(135deg, rgb(var(--text-muted)) 50%, transparent 50%);
      background-position: calc(100% - 16px) 14px, calc(100% - 11px) 14px;
      background-size: 5px 5px, 5px 5px; background-repeat: no-repeat; }
    .input-group { position: relative; }
    .input-group .input { padding-left: 32px; }
    .input-group .input-icon { position: absolute; left: 11px; top: 50%; transform: translateY(-50%); color: rgb(var(--text-muted)); font-size: 12px; pointer-events: none; }
    .field-error { color: #f87171; font-size: 12px; margin-top: 5px; }
    .input.invalid { border-color: rgb(var(--error)); }

    .switch { display: inline-flex; align-items: center; gap: 8px; cursor: pointer; user-select: none; font-size: 12.5px; color: rgb(var(--text-dim)); }
    .switch input { position: absolute; opacity: 0; width: 0; height: 0; }
    .switch .track { width: 34px; height: 20px; border-radius: 99px; background: rgb(var(--surface-3)); border: 1px solid var(--line); position: relative; transition: .18s; flex: none; }
    .switch .track::after { content: ""; position: absolute; top: 2px; left: 2px; width: 14px; height: 14px; border-radius: 99px; background: #fff; transition: .18s; }
    .switch input:checked + .track { background: rgb(var(--primary)); border-color: rgb(var(--primary)); }
    .switch input:checked + .track::after { transform: translateX(14px); }
    .switch input:focus-visible + .track { outline: 2px solid rgb(var(--primary)); outline-offset: 2px; }

    /* ---------- tabs ---------- */
    .tabs { display: flex; gap: 4px; border-bottom: 1px solid var(--line); overflow-x: auto; }
    .tabs::-webkit-scrollbar { height: 0; }
    .tab {
      display: inline-flex; align-items: center; gap: 7px; padding: 9px 12px;
      border-radius: 9px 9px 0 0; font-size: 13px; font-weight: 600; color: rgb(var(--text-dim));
      cursor: pointer; border: 1px solid transparent; border-bottom: none; white-space: nowrap; background: transparent;
    }
    .tab:hover { color: rgb(var(--text)); background: rgb(var(--surface-2)); }
    .tab.active { color: rgb(var(--text)); background: rgb(var(--surface)); border-color: var(--line); position: relative; top: 1px; }
    .tab .count { font-size: 11px; background: rgb(var(--surface-3)); border-radius: 99px; padding: 1px 7px; color: rgb(var(--text-dim)); }
    .tab.active .count { background: rgb(var(--primary) / .18); color: #a5b4fc; }

    /* ---------- table ---------- */
    .table { width: 100%; border-collapse: separate; border-spacing: 0; font-size: 13px; }
    .table th {
      text-align: left; font-weight: 600; color: rgb(var(--text-dim)); font-size: 11px;
      text-transform: uppercase; letter-spacing: .05em; padding: 10px 12px;
      border-bottom: 1px solid var(--line); white-space: nowrap;
      background: rgb(var(--surface)); position: sticky; top: 0; z-index: 5;
    }
    .table td { padding: 10px 12px; border-bottom: 1px solid var(--line); vertical-align: middle; }
    .table tbody tr { transition: background .12s; cursor: pointer; }
    .table tbody tr:hover { background: rgb(var(--surface-2) / .65); }
    .table tbody tr.selected { background: rgb(var(--primary) / .1); }
    .table tbody tr:last-child td { border-bottom: none; }
    .table .num { text-align: right; }

    /* ---------- meters / charts ---------- */
    .meter { height: 6px; background: rgb(var(--surface-3)); border-radius: 99px; overflow: hidden; }
    .meter-fill { height: 100%; border-radius: 99px; background: rgb(var(--primary)); transition: width .4s cubic-bezier(.4,0,.2,1); }
    .meter-fill.success { background: rgb(var(--success)); }
    .meter-fill.warning { background: rgb(var(--warning)); }
    .meter-fill.error { background: rgb(var(--error)); }
    .bars { display: flex; align-items: flex-end; gap: 2px; height: 44px; }
    .bars > span { flex: 1 1 0; min-width: 3px; border-radius: 3px; background: rgb(var(--success)); display: block; transition: height .3s; }
    .bars > span.warning { background: rgb(var(--warning)); }
    .bars > span.error { background: rgb(var(--error)); }

    .port { display: inline-flex; align-items: center; gap: 5px; font-size: 12px; font-family: "SF Mono", ui-monospace, Menlo, monospace; color: #a5b4fc; }
    .port.muted { color: rgb(var(--text-muted)); }

    .kpi { display: flex; flex-direction: column; gap: 2px; padding: 12px 14px; }
    .kpi .v { font-size: 22px; font-weight: 700; letter-spacing: -.02em; line-height: 1.1; }
    .kpi .l { font-size: 11px; text-transform: uppercase; letter-spacing: .05em; color: rgb(var(--text-muted)); }

    /* ---------- dropdown menu ---------- */
    .menu-pop {
      position: fixed; z-index: 70; min-width: 194px; padding: 5px;
      background: rgb(var(--surface-2)); border: 1px solid var(--line-strong);
      border-radius: 12px; box-shadow: var(--shadow);
    }
    .menu-item {
      display: flex; align-items: center; gap: 9px; width: 100%; padding: 8px 9px;
      border: none; background: transparent; color: rgb(var(--text)); font-size: 13px;
      border-radius: 8px; cursor: pointer; text-align: left;
    }
    .menu-item:hover { background: rgb(var(--surface-3)); }
    .menu-item.danger { color: #f87171; }
    .menu-sep { height: 1px; background: var(--line); margin: 5px 4px; }

    /* ---------- drawer ---------- */
    .drawer-backdrop { position: fixed; inset: 0; background: rgba(0,0,0,.5); z-index: 40; opacity: 0; pointer-events: none; transition: opacity .2s; }
    .drawer-backdrop.open { opacity: 1; pointer-events: auto; }
    .drawer {
      position: fixed; top: 0; right: 0; height: 100vh; width: min(620px, 100%);
      background: rgb(var(--surface)); border-left: 1px solid var(--line); z-index: 41;
      transform: translateX(101%); transition: transform .26s cubic-bezier(.4,0,.2,1);
      display: flex; flex-direction: column;
    }
    .drawer.open { transform: none; box-shadow: -30px 0 70px rgba(0,0,0,.5); }

    /* ---------- modal ---------- */
    .modal { position: fixed; inset: 0; display: grid; place-items: center; background: rgba(0,0,0,.62); z-index: 60; padding: 20px; }
    .modal-box {
      background: rgb(var(--surface)); border: 1px solid var(--line-strong); border-radius: 14px;
      box-shadow: 0 24px 80px rgba(0,0,0,.6); width: 100%; max-width: 560px;
      max-height: 88vh; display: flex; flex-direction: column; overflow: hidden;
    }

    /* ---------- toasts ---------- */
    .toast-root { position: fixed; top: 14px; right: 14px; z-index: 90; display: flex; flex-direction: column; gap: 8px; width: min(360px, 92vw); }
    .toast {
      background: rgb(var(--surface-2)); border: 1px solid var(--line-strong);
      border-left: 3px solid rgb(var(--primary)); border-radius: 10px; padding: 11px 13px;
      box-shadow: var(--shadow); display: flex; gap: 10px; align-items: flex-start;
      animation: slidein .18s ease;
    }
    .toast.success { border-left-color: rgb(var(--success)); }
    .toast.error { border-left-color: rgb(var(--error)); }
    .toast.warning { border-left-color: rgb(var(--warning)); }
    @keyframes slidein { from { opacity: 0; transform: translateY(-6px); } to { opacity: 1; transform: none; } }

    /* ---------- misc ---------- */
    .skeleton {
      background: linear-gradient(90deg, rgb(var(--surface-2)), rgb(var(--surface-3)), rgb(var(--surface-2)));
      background-size: 200% 100%; animation: shimmer 1.4s infinite; border-radius: 8px;
    }
    @keyframes shimmer { 0% { background-position: 200% 0; } 100% { background-position: -200% 0; } }
    .spin { animation: spin 1s linear infinite; }
    @keyframes spin { to { transform: rotate(360deg); } }
    .nav-item {
      display: flex; align-items: center; gap: 10px; padding: 8px 10px; margin: 1px 8px;
      border-radius: 9px; font-size: 13.5px; color: rgb(var(--text-dim)); cursor: pointer; border: 1px solid transparent;
    }
    .nav-item:hover { background: rgb(var(--surface-2)); color: rgb(var(--text)); }
    .nav-item.active { background: rgb(var(--primary) / .14); color: #c7d2fe; border-color: rgb(var(--primary) / .28); }
    .nav-item .ico { width: 18px; text-align: center; font-size: 13px; }
    .nav-label { font-size: 10.5px; text-transform: uppercase; letter-spacing: .08em; color: rgb(var(--text-muted)); padding: 14px 18px 6px; font-weight: 700; }
    .scroll-y { overflow-y: auto; }
    .mock-controls { position: fixed; right: 14px; bottom: 14px; z-index: 55; }
    .mock-panel {
      background: rgb(var(--surface-2)); border: 1px dashed rgb(var(--warning) / .5);
      border-radius: 12px; padding: 13px; width: 258px; box-shadow: var(--shadow);
    }
    .log-line { display: flex; gap: 10px; padding: 2px 0; font-size: 12px; line-height: 1.55; }
    .log-line .ts { color: rgb(var(--text-muted)); flex: none; }
    .log-line .lv { flex: none; width: 44px; font-weight: 700; }
    .log-line .msg { white-space: pre-wrap; word-break: break-word; }
    .lv-INFO { color: #38bdf8; } .lv-WARN { color: #fbbf24; } .lv-ERROR { color: #f87171; } .lv-DEBUG { color: rgb(var(--text-muted)); }
    code.k {
      background: rgb(var(--surface-3)); border: 1px solid var(--line); border-radius: 6px;
      padding: 1px 6px; font-size: 12px;
    }

    @media (prefers-reduced-motion: reduce) {
      *, *::before, *::after { transition: none !important; animation: none !important; }
    }
    @media (max-width: 1024px) {
      .sidebar { display: none; }
    }
  </style>
</head>

<body>
  <noscript>
    <div style="padding:24px">This mockup needs JavaScript to render the Infrastructure view.</div>
  </noscript>

  <!-- MOCK: shell — static chrome + dynamic mount points -->
  <div class="app">
    <!-- ======================= SIDEBAR ======================= -->
    <aside class="sidebar">
      <div class="flex items-center gap-2 px-4 h-14 border-b border-white/5">
        <span class="grid place-items-center w-7 h-7 rounded-lg" style="background:rgb(var(--primary)/.16)">
          <i class="fa-solid fa-cube text-primary-light" aria-hidden="true"></i>
