        if (c.state === 'running' && c.started_at) {
          c.uptime_seconds = Math.max(0, Math.floor((Date.now() - new Date(c.started_at).getTime()) / 1000))
        }
        if (!c.status_text) {
          if (c.state === 'running') c.status_text = 'Up ' + fmtDuration(c.uptime_seconds)
          else if (c.state === 'restarting') c.status_text = 'Restarting (' + (c.restart_count || 1) + ') 5 seconds ago'
          else if (c.state === 'paused') c.status_text = 'Up ' + fmtDuration(c.uptime_seconds) + ' (Paused)'
          else if (c.state === 'exited') c.status_text = 'Exited (0) 2 hours ago'
          else if (c.state === 'created') c.status_text = 'Created'
        }
      })
    }
    applyDerived()

    function hostContainers(hostId) { return DB.containers.filter(c => c.host_id === hostId) }

    function buildSummary(hostId) {
      const host = DB.hosts.find(h => h.id === hostId) || DB.hosts[0]
      const list = hostContainers(hostId)
      const running = list.filter(c => c.state === 'running')
      const counts = {
        total: list.length,
        running: running.length,
        stopped: list.filter(c => c.state === 'exited' || c.state === 'created').length,
        paused: list.filter(c => c.state === 'paused').length,
        restarting: list.filter(c => c.state === 'restarting').length,
        unhealthy: list.filter(c => c.health === 'unhealthy').length,
        images: activeImages(hostId).filter(i => !i.dangling).length,
        volumes: activeVolumes(hostId).length,
        networks: activeNetworks(hostId).length
      }
      return {
        host,
        engine: host.engine,
        cpu_pct: host.cpu_pct,
        cpu_cores: host.cpu_cores,
        mem_used: host.mem_used, mem_total: host.mem_total,
        disk_used: host.disk_used, disk_total: host.disk_total,
        counts
      }
    }

    function imageUsed(c) { return DB.containers.filter(x => (x.image === c)) }
    function activeImages(hostId) {
      return DB.images.filter(i => {
        const used = DB.containers.some(c => c.host_id === hostId && (c.image === i.repo + ':' + i.tag))
        return used || i.dangling
      }).map(i => Object.assign({}, i, {
        containers: DB.containers.filter(c => c.host_id === hostId && c.image === i.repo + ':' + i.tag).length
      }))
    }
    function activeVolumes(hostId) {
      return DB.volumes.filter(v => (v.host_id || 'host-local') === hostId).map(v => Object.assign({}, v, {
        in_use: DB.containers.some(c => c.host_id === hostId && c.mounts.some(m => m.source === v.name))
      }))
    }
    function activeNetworks(hostId) {
      const base = DB.networks.filter(n => (n.host_id || 'host-local') === hostId || n.host_id == null && hostId === 'host-local')
      const all = DB.networks.filter(n => (n.host_id || 'host-local') === hostId)
      return all.map(n => Object.assign({}, n, {
        containers: DB.containers.filter(c => c.host_id === hostId && c.networks.some(cn => cn.name === n.name)).map(c => c.name)
      }))
    }
    function buildStacks(hostId) {
      const map = {}
      hostContainers(hostId).forEach(c => {
        if (!c.stack) return
        map[c.stack] = map[c.stack] || { name: c.stack, host_id: hostId, services: [] }
        map[c.stack].services.push({ service: c.service, name: c.name, state: c.state, health: c.health, id: c.id })
      })
      return Object.values(map).map(s => {
        const running = s.services.filter(x => x.state === 'running').length
        s.status = running === s.services.length ? 'running' : running === 0 ? 'stopped' : 'degraded'
        s.running = running
        s.total = s.services.length
        s.path = '/opt/codx-junior/' + s.name + '/docker-compose.yaml'
        return s
