      { method: 'GET', path: /^\/api\/infra\/containers\/([^/]+)\/stats$/, handler: ({ params }) => {
        const c = findContainer(params[0]) || {}
        const series = []
        let cpu = c.cpu_pct || 1, mem = c.mem_used || 0
        for (let i = 39; i >= 0; i--) {
          cpu = Math.max(0, cpu + (rnd() - 0.5) * Math.max(0.4, (c.cpu_pct || 1) * 0.25))
          mem = Math.max(0, mem + (rnd() - 0.5) * (c.mem_limit || GiB) * 0.02)
          series.push({ t: isoAgo(MIN * i * 1.5), cpu: +cpu.toFixed(1), mem: Math.round(Math.min(mem, c.mem_limit || GiB)) })
        }
        return {
          current: {
            cpu_pct: c.cpu_pct || 0, mem_used: c.mem_used || 0, mem_limit: c.mem_limit || 0,
            net_rx: c.net_rx || 0, net_tx: c.net_tx || 0,
