        }
      }},

      { method: 'POST', path: /^\/api\/infra\/containers\/([^/]+)\/actions$/, handler: ({ params, body }) => {
        const c = findContainer(params[0]); if (!c) return null
        const a = body.action
        if (a === 'start' || a === 'restart') {
          c.state = 'running'
          c.health = c.health === 'unhealthy' ? c.health : (c.healthcheck ? 'starting' : c.health)
          c.started_at = new Date().toISOString()
          c.uptime_seconds = 0
          if (a === 'restart') c.restart_count = (c.restart_count || 0) + 1
        } else if (a === 'stop' || a === 'kill') {
          c.state = 'exited'; c.health = null; c.cpu_pct = 0; c.mem_used = 0
        } else if (a === 'pause') {
          c.state = 'paused'; c.cpu_pct = 0
        } else if (a === 'unpause') {
          c.state = 'running'
        }
        c.status_text = null; delete c.status_text
