      route: 'containers',        // containers | stacks | images | volumes | networks | events
      hostId: 'host-local',
      status: 'idle',             // idle | loading | ready | error
      error: null,
      lastUpdated: null,
      autoRefresh: false,
      filters: { q: '', state: 'all', stack: 'all', sort: 'name' },
      containers: [],
      summary: null,
      stacks: [],
      images: [],
      volumes: [],
      networks: [],
      events: [],
      selected: [],               // bulk selection ids
      selectedId: null,           // drawer container id
      drawerTab: 'overview',
      drawer: { logs: null, stats: null, loadingLogs: false, loadingStats: false, tail: 120 },
      menu: null,                 // { x, y, id }
      modal: null,
      toasts: [],
      mockPanelOpen: false,
      __forceFail: false,
      __forceEmpty: false,
      _timer: null
    }

    function persistState() {
      try {
        localStorage.setItem(LS_KEY, JSON.stringify({
          route: state.route, hostId: state.hostId, autoRefresh: state.autoRefresh,
          filters: state.filters, selectedId: state.selectedId, drawerTab: state.drawerTab
        }))
      } catch (e) { /* storage disabled — ignore */ }
    }
    function persistMutations() {
      try {
        localStorage.setItem(LS_MUT, JSON.stringify(DB.containers.map(c => ({
          id: c.id, name: c.name, state: c.state, health: c.health,
          started_at: c.started_at, restart_count: c.restart_count, mem_used: c.mem_used, cpu_pct: c.cpu_pct
        }))))
      } catch (e) { /* ignore */ }
    }
    function restoreMutations() {
      try {
        const raw = localStorage.getItem(LS_MUT)
        if (!raw) return
        JSON.parse(raw).forEach(m => {
          const c = DB.containers.find(x => x.id === m.id)
          if (c) Object.assign(c, { state: m.state, health: m.health, started_at: m.started_at, restart_count: m.restart_count })
        })
        applyDerived()
      } catch (e) { /* ignore */ }
    }
    function resetMock() {
      localStorage.removeItem(LS_KEY)
      localStorage.removeItem(LS_MUT)
      location.reload()
    }

    /* =======================================================================
       E. ACTIONS
       ======================================================================= */
    function toast(text, kind) {
      const id = 't' + Math.random().toString(36).slice(2)
      state.toasts.push({ id, text, kind: kind || 'info' })
      renderToasts()
      setTimeout(() => { state.toasts = state.toasts.filter(t => t.id !== id); renderToasts() }, 4200)
    }

    function setRoute(route) {
      state.route = route
      if (location.hash !== '#/' + route) location.hash = '#/' + route
      state.selected = []
      state.filters.q = ''
      persistState()
      renderTab()
    }

    function setHost(hostId) {
      state.hostId = hostId
      state.selected = []
      state.selectedId = null
      persistState()
      loadAll()
    }

    function toggleSelect(id, checked) {
      if (checked) { if (!state.selected.includes(id)) state.selected.push(id) }
      else state.selected = state.selected.filter(x => x !== id)
      renderResults()
    }

    function openMenu(ev, id) {
      ev.stopPropagation()
      const r = ev.currentTarget.getBoundingClientRect()
      const w = 200
      state.menu = { id, x: Math.min(r.right - w, window.innerWidth - w - 8), y: Math.min(r.bottom + 6, window.innerHeight - 320) }
      renderMenu()
    }
    function closeMenu() { if (state.menu) { state.menu = null; renderMenu() } }

    function openDrawer(id, tab) {
      state.selectedId = id
      state.drawerTab = tab || state.drawerTab || 'overview'
      state.drawer.logs = null; state.drawer.stats = null
      persistState()
      renderDrawer()
      if (state.drawerTab === 'logs') loadLogs(id)
      if (state.drawerTab === 'stats') loadStats(id)
    }
    function closeDrawer() { state.selectedId = null; persistState(); renderDrawer() }

    async function loadLogs(id) {
      state.drawer.loadingLogs = true; state.drawer.logs = null; renderDrawer()
      try {
        const r = await apiGet('/api/infra/containers/' + id + '/logs?tail=' + state.drawer.tail)
        if (state.selectedId !== id) return
        state.drawer.logs = r.lines
      } catch (e) { toast(e.message, 'error') }
      finally { state.drawer.loadingLogs = false; renderDrawer() }
    }
    async function loadStats(id) {
      state.drawer.loadingStats = true; state.drawer.stats = null; renderDrawer()
      try {
        const r = await apiGet('/api/infra/containers/' + id + '/stats')
        if (state.selectedId !== id) return
        state.drawer.stats = r
      } catch (e) { toast(e.message, 'error') }
      finally { state.drawer.loadingStats = false; renderDrawer() }
    }

    async function containerAction(id, action) {
      const prev = findContainer(id)
      try {
        const c = await apiPost('/api/infra/containers/' + id + '/actions', { action })
        const i = state.containers.findIndex(x => x.id === id)
        const live = state.summary && c.host_id === state.hostId
        if (i >= 0) state.containers[i] = c
        const dbc = findContainer(id); if (dbc) Object.assign(dbc, c)
        applyDerived()
        persistMutations()
        toast((prev ? prev.name : id) + ' → ' + action, action === 'stop' || action === 'kill' ? 'warning' : 'success')
        await refreshSummary()
        renderResults(); renderDrawer(); renderHostStrip(); renderTabs()
      } catch (e) { toast(e.message, 'error') }
    }

    async function bulkAction(action) {
      const ids = state.selected.slice()
      if (!ids.length) return
      toast('Running "' + action + '" on ' + ids.length + ' container(s)…', 'info')
      for (const id of ids) { await containerActionNoToast(id, action) }
      toast('Bulk ' + action + ' completed for ' + ids.length + ' container(s)', 'success')
      state.selected = []
      await refreshSummary()
      renderResults(); renderHostStrip()
    }
    async function containerActionNoToast(id, action) {
      try {
        const c = await apiPost('/api/infra/containers/' + id + '/actions', { action })
        const i = state.containers.findIndex(x => x.id === id)
        if (i >= 0) state.containers[i] = c
        const dbc = findContainer(id); if (dbc) Object.assign(dbc, c)
        persistMutations()
      } catch (e) { /* keep going on bulk */ }
    }

    function confirmDialog(opts) {
      state.modal = Object.assign({ type: 'confirm', confirmText: 'Confirm', cancelText: 'Cancel', danger: false }, opts)
      renderModal()
    }
    function closeModal() { state.modal = null; renderModal() }

    async function deleteContainer(id) {
      const c = findContainer(id)
      confirmDialog({
        title: 'Remove container',
        html: 'Remove <b>' + esc(c ? c.name : id) + '</b>? This stops the container and deletes it. Volumes are kept.',
        confirmText: 'Remove container', danger: true,
        onConfirm: async () => {
          closeModal()
          try {
            await apiDelete('/api/infra/containers/' + id)
            state.containers = state.containers.filter(x => x.id !== id)
            const idx = DB.containers.findIndex(x => x.id === id); if (idx >= 0) DB.containers.splice(idx, 1)
            if (state.selectedId === id) closeDrawer()
            persistMutations()
            toast('Container removed: ' + (c ? c.name : id), 'success')
            await refreshSummary()
            renderResults(); renderHostStrip(); renderTabs()
          } catch (e) { toast(e.message, 'error') }
        }
      })
    }

    function openRunModal() {
      state.modal = {
        type: 'run',
        form: { name: '', image: '', ports: '', env: '', cmd: '', stack: 'adhoc' },
        errors: {}, submitting: false
      }
      renderModal()
      setTimeout(() => { const el = document.getElementById('run-name'); if (el) el.focus() }, 30)
    }

    async function submitRun() {
      const f = state.modal.form
      const errors = {}
      if (!f.name.trim()) errors.name = 'Container name is required'
      if (!/^[a-zA-Z0-9][a-zA-Z0-9_.-]*$/.test(f.name.trim())) errors.name = errors.name || 'Use letters, digits, _ . - only'
      if (!f.image.trim()) errors.image = 'Image reference is required (e.g. redis:7-alpine)'
      state.modal.errors = errors
      if (Object.keys(errors).length) { renderModal(); return }

      state.modal.submitting = true; renderModal()
      try {
        const ports = f.ports.split(',').map(s => s.trim()).filter(Boolean).map(p => {
          const [h, c] = p.split(':')
          return { host: Number(h), container: Number(c || h), proto: 'tcp' }
        })
        const env = f.env.split(/[\n,]/).map(s => s.trim()).filter(Boolean).map(kv => {
          const i = kv.indexOf('='); return { k: i < 0 ? kv : kv.slice(0, i), v: i < 0 ? '' : kv.slice(i + 1) }
        })
        const c = await apiPost('/api/infra/containers', { name: f.name.trim(), image: f.image.trim(), ports, env, cmd: f.cmd, stack: f.stack })
        closeModal()
        toast('Started container "' + c.name + '"', 'success')
        await loadAll()
        openDrawer(c.id, 'overview')
      } catch (e) {
        state.modal.submitting = false
        toast(e.message, 'error')
        renderModal()
      }
    }

    /* =======================================================================
       F. RENDER
       ======================================================================= */

    // ---- host strip (KPI + gauges) ----
    function renderHostStrip() {
      const el = document.getElementById('host-strip')
      if (!el) return
      const s = state.summary
      if (!s) { el.innerHTML = stripSkeleton(); return }
      const c = s.counts
      const memPct = Math.round((s.mem_used / s.mem_total) * 100)
      const diskPct = Math.round((s.disk_used / s.disk_total) * 100)

      el.innerHTML = ''
      el.className = 'grid gap-3 mb-4 grid-cols-2 md:grid-cols-3 xl:grid-cols-6'
      el.innerHTML = `
        <div class="card"><div class="kpi">
          <span class="l">CPU (${s.cpu_cores} cores)</span>
          <span class="v">${s.cpu_pct}<span class="text-sm text-dim">%</span></span>
          <div class="meter mt-1 mb-1"><div class="meter-fill ${tone(s.cpu_pct, 85, 65)}" style="width:${Math.min(100, s.cpu_pct)}%"></div></div>
          <span class="text-[11px] text-muted">load avg ${(s.cpu_pct / 100 * s.cpu_cores).toFixed(2)}</span>
        </div></div>

        <div class="card"><div class="kpi">
          <span class="l">Memory</span>
          <span class="v">${memPct}<span class="text-sm text-dim">%</span></span>
          <div class="meter mt-1 mb-1"><div class="meter-fill ${tone(memPct, 85, 65)}" style="width:${memPct}%"></div></div>
          <span class="text-[11px] text-muted">${fmtBytes(s.mem_used)} / ${fmtBytes(s.mem_total)}</span>
        </div></div>

        <div class="card"><div class="kpi">
          <span class="l">Disk</span>
          <span class="v">${diskPct}<span class="text-sm text-dim">%</span></span>
          <div class="meter mt-1 mb-1"><div class="meter-fill ${tone(diskPct, 85, 70)}" style="width:${diskPct}%"></div></div>
          <span class="text-[11px] text-muted">${fmtBytes(s.disk_used)} / ${fmtBytes(s.disk_total)}</span>
        </div></div>

        <div class="card"><div class="kpi">
          <span class="l">Containers</span>
          <span class="v">${c.running}<span class="text-sm text-dim">/${c.total}</span></span>
          <div class="flex flex-wrap gap-1 mt-1">
            <span class="badge badge-xs badge-success"><span class="dot"></span>${c.running} up</span>
            <span class="badge badge-xs badge-neutral">${c.stopped} stopped</span>
            ${c.paused ? '<span class="badge badge-xs badge-info">' + c.paused + ' paused</span>' : ''}
            ${c.restarting ? '<span class="badge badge-xs badge-warning">' + c.restarting + ' restarting</span>' : ''}
            ${c.unhealthy ? '<span class="badge badge-xs badge-error">' + c.unhealthy + ' unhealthy</span>' : ''}
          </div>
        </div></div>

        <div class="card"><div class="kpi">
          <span class="l">Images</span>
          <span class="v">${c.images}</span>
          <span class="text-[11px] text-muted">Engine ${esc(s.engine)}</span>
        </div></div>

        <div class="card"><div class="kpi">
          <span class="l">Volumes · Networks</span>
          <span class="v">${c.volumes}<span class="text-sm text-dim"> · ${c.networks}</span></span>
          <span class="text-[11px] text-muted">${esc(s.host.name)}</span>
        </div></div>
      `
    }
    function stripSkeleton() {
      let cells = ''
      for (let i = 0; i < 6; i++) cells += `<div class="card"><div class="kpi">
        <div class="skeleton" style="height:10px;width:60%"></div>
        <div class="skeleton mt-2" style="height:22px;width:40%"></div>
        <div class="skeleton mt-2" style="height:8px;width:100%"></div>
      </div></div>`
      return cells
    }

    // ---- tabs ----
    const TABS = [
      { id: 'containers', label: 'Containers', icon: 'cube' },
      { id: 'stacks', label: 'Stacks', icon: 'layer-group' },
      { id: 'images', label: 'Images', icon: 'box-archive' },
      { id: 'volumes', label: 'Volumes', icon: 'database' },
      { id: 'networks', label: 'Networks', icon: 'network-wired' },
      { id: 'events', label: 'Events', icon: 'bolt' }
    ]
    function tabCount(id) {
      switch (id) {
        case 'containers': return state.containers.length
        case 'stacks': return state.stacks.length
        case 'images': return state.images.length
        case 'volumes': return state.volumes.length
        case 'networks': return state.networks.length
        case 'events': return state.events.length
      }
      return 0
    }
    function renderTabs() {
      const el = document.getElementById('tabs')
      if (!el) return
      el.innerHTML = TABS.map(t => `
        <button class="tab ${state.route === t.id ? 'active' : ''}" data-route="${t.id}"
          role="tab" aria-selected="${state.route === t.id}">
          ${icon(t.icon)} ${t.label} <span class="count">${tabCount(t.id)}</span>
        </button>`).join('')
    }

    // ---- main view render ----
    function render() {
      const view = document.getElementById('view')
      if (!view) return

      view.innerHTML = `
        <div class="view-head flex flex-wrap items-start gap-3 mb-4">
          <div class="min-w-0">
            <h1 class="text-[22px] font-bold leading-tight flex items-center gap-2">
              ${icon('server')} Infrastructure
            </h1>
            <p class="text-dim text-[13px] mt-0.5">
              Every container deployed on your Docker host — state, resources, ports and logs.
            </p>
          </div>
          <div class="grow"></div>
          <div class="flex flex-wrap items-center gap-2">
            <label class="sr-only" for="host-select">Host</label>
            <select class="select input-sm" id="host-select" style="width:auto;min-width:210px">
              ${DB.hosts.map(h => `<option value="${h.id}" ${h.id === state.hostId ? 'selected' : ''}>
                ${h.is_local ? '🐳' : '🛰️'} ${esc(h.name)}</option>`).join('')}
            </select>
            <label class="switch" title="Poll for live CPU / memory every 3s">
              <input type="checkbox" id="auto-refresh" role="switch" ${state.autoRefresh ? 'checked' : ''} />
              <span class="track"></span>
              <span>Live</span>
            </label>
            <button class="btn btn-sm" id="refresh-btn" aria-label="Refresh data">${icon('arrows-rotate')} Refresh</button>
            <button class="btn btn-sm btn-primary" id="run-btn">${icon('plus')} Run container</button>
          </div>
        </div>

        <div id="host-strip" class="grid gap-3 mb-4 grid-cols-2 md:grid-cols-3 xl:grid-cols-6"></div>

        <div class="text-[11.5px] text-muted mb-2 flex items-center gap-2">
          ${icon('clock')} <span id="last-updated">${state.lastUpdated ? 'Updated ' + fmtTime(state.lastUpdated.toISOString()) : 'Not loaded'}</span>
        </div>

        <div class="tabs mb-0" id="tabs" role="tablist"></div>
        <div id="tab-content" class="mt-4"></div>
      `

      renderHostStrip()
      renderTabs()
      renderTab()
    }

    // ---- tab content ----
    function renderTab() {
      const el = document.getElementById('tab-content')
      if (!el) return

      if (state.status === 'loading' || state.status === 'idle') { el.innerHTML = tabSkeleton(); return }
      if (state.status === 'error') { el.innerHTML = errorPanel(); return }

      el.innerHTML = `
        ${filtersBar()}
        <div id="results"></div>
      `
      renderResults()
    }

    function tabSkeleton() {
      let rows = ''
      for (let i = 0; i < 7; i++) rows += `<tr>${'<td><div class="skeleton" style="height:12px;width:80%"></div></td>'.repeat(7)}</tr>`
      return `
        <div class="card overflow-hidden">
          <div class="p-3"><div class="skeleton" style="height:30px;width:280px"></div></div>
          <table class="table"><tbody>${rows}</tbody></table>
        </div>`
    }

    function errorPanel() {
      return `
        <div class="card card-pad text-center py-12">
          <div class="text-error text-3xl mb-3">${icon('triangle-exclamation')}</div>
          <h3 class="font-bold text-lg">Could not reach the Docker daemon</h3>
          <p class="text-dim text-sm mt-1 mb-4 max-w-md mx-auto">${esc(state.error || 'Unknown error')}</p>
          <div class="flex justify-center gap-2">
            <button class="btn btn-sm btn-primary" data-action="reload">${icon('rotate-right')} Retry</button>
            <button class="btn btn-sm" data-action="reset-mock">${icon('broom')} Reset mock data</button>
          </div>
        </div>`
    }

    function emptyPanel(title, hint, cta) {
      return `
        <div class="card card-pad text-center py-12">
          <div class="text-muted text-3xl mb-3">${icon('box-open')}</div>
          <h3 class="font-bold text-base">${title}</h3>
          <p class="text-dim text-sm mt-1 mb-4">${hint}</p>
          ${cta || ''}
        </div>`
    }

    // ---- filters ----
    function filtersBar() {
      const r = state.route
      const placeholder = {
        containers: 'Search by name, image, service, stack…',
        stacks: 'Search stacks…',
        images: 'Search repository or tag…',
        volumes: 'Search volumes…',
        networks: 'Search networks…',
        events: 'Filter events by actor…'
      }[r]

      const stateFilter = r === 'containers' ? `
        <label class="sr-only" for="filter-state">State</label>
        <select class="select input-sm" id="filter-state" style="width:auto;min-width:150px">
          ${['all', 'running', 'exited', 'restarting', 'paused', 'unhealthy'].map(s => {
            const lbl = s === 'all' ? 'All states' : s === 'unhealthy' ? 'Unhealthy' : s[0].toUpperCase() + s.slice(1)
            return `<option value="${s}" ${state.filters.state === s ? 'selected' : ''}>${lbl}</option>`
          }).join('')}
        </select>` : ''

      const stackFilter = (r === 'containers' || r === 'stacks') ? `
        <label class="sr-only" for="filter-stack">Stack</label>
        <select class="select input-sm" id="filter-stack" style="width:auto;min-width:150px">
          <option value="all">All stacks</option>
          ${state.stacks.map(s => `<option value="${s.name}" ${state.filters.stack === s.name ? 'selected' : ''}>${esc(s.name)}</option>`).join('')}
        </select>` : ''

      const sortFilter = (r === 'containers' || r === 'images' || r === 'volumes') ? `
        <label class="sr-only" for="filter-sort">Sort</label>
        <select class="select input-sm" id="filter-sort" style="width:auto;min-width:150px">
          ${[['name', 'Name'], ['cpu', 'CPU %'], ['mem', 'Memory'], ['created', 'Created']].map(([v, l]) =>
            `<option value="${v}" ${state.filters.sort === v ? 'selected' : ''}>${l}</option>`).join('')}
        </select>` : ''

      return `
        <div class="flex flex-wrap items-center gap-2 mb-3">
          <div class="input-group" style="flex:1 1 260px;max-width:380px">
            <i class="fa-solid fa-magnifying-glass input-icon"></i>
            <input class="input input-sm" id="filter-q" placeholder="${placeholder}" value="${esc(state.filters.q)}" aria-label="Search" />
          </div>
          ${stateFilter}${stackFilter}${sortFilter}
          <div class="grow"></div>
          <span class="text-[11.5px] text-muted" id="result-count"></span>
        </div>
        <div id="bulk-bar"></div>
      `
    }

    // ---- results dispatch ----
    function renderResults() {
      const el = document.getElementById('results')
      if (!el) return
      switch (state.route) {
        case 'containers': el.innerHTML = containersTable(); renderBulk(); break
        case 'stacks': el.innerHTML = stacksView(); break
        case 'images': el.innerHTML = imagesTable(); break
        case 'volumes': el.innerHTML = volumesTable(); break
        case 'networks': el.innerHTML = networksTable(); break
        case 'events': el.innerHTML = eventsView(); break
      }
      const rc = document.getElementById('result-count')
      if (rc) rc.textContent = filteredList().length + ' item(s)'
    }

    function filteredList() {
      const f = state.filters
      const term = f.q.trim().toLowerCase()
      let list
      if (state.route === 'containers') list = state.containers.slice()
      else if (state.route === 'stacks') list = state.stacks.slice()
      else if (state.route === 'images') list = state.images.slice()
      else if (state.route === 'volumes') list = state.volumes.slice()
      else if (state.route === 'networks') list = state.networks.slice()
      else list = state.events.slice()

      if (term) {
        list = list.filter(x => JSON.stringify(x).toLowerCase().includes(term))
      }
      if (state.route === 'containers') {
        if (f.state !== 'all') list = list.filter(c => f.state === 'unhealthy' ? c.health === 'unhealthy' : c.state === f.state)
        if (f.stack !== 'all') list = list.filter(c => c.stack === f.stack)
      }
      if (state.route === 'stacks' && f.stack !== 'all') list = list.filter(s => s.name === f.stack)

      const s = f.sort
      const cmp = (a, b) => String(a).localeCompare(String(b))
      if (s === 'cpu') list.sort((a, b) => (b.cpu_pct || 0) - (a.cpu_pct || 0))
      else if (s === 'mem') list.sort((a, b) => (b.mem_used || 0) - (a.mem_used || 0))
      else if (s === 'created') list.sort((a, b) => String(b.created).localeCompare(String(a.created)))
      else list.sort((a, b) => cmp(a.name || a.repo || a.ts, b.name || b.repo || b.ts))
      return list
    }

    // ---- containers table ----
    function stateMeta(c) {
      if (c.state === 'running' && c.health === 'unhealthy') return { label: 'Unhealthy', key: 'error', dot: 'rgb(var(--error))' }
      if (c.state === 'running' && c.health === 'starting') return { label: 'Starting', key: 'warning', dot: 'rgb(var(--warning))' }
      if (c.state === 'running' && c.health === 'healthy') return { label: 'Healthy', key: 'success', dot: 'rgb(var(--success))' }
      if (c.state === 'running') return { label: 'Running', key: 'success', dot: 'rgb(var(--success))' }
      if (c.state === 'restarting') return { label: 'Restarting', key: 'warning', dot: 'rgb(var(--warning))' }
      if (c.state === 'paused') return { label: 'Paused', key: 'info', dot: 'rgb(var(--info))' }
      if (c.state === 'exited') return { label: 'Exited', key: 'neutral', dot: 'rgb(var(--text-muted))' }
      if (c.state === 'created') return { label: 'Created', key: 'info', dot: 'rgb(var(--info))' }
      return { label: c.state, key: 'neutral', dot: 'rgb(var(--text-muted))' }
    }

    function cpuCell(c) {
      const p = c.state === 'running' ? (c.cpu_pct || 0) : 0
      return `<div class="flex items-center gap-2 min-w-[96px]">
        <div class="meter" style="width:44px"><div class="meter-fill ${tone(p, 70, 40)}" style="width:${Math.min(100, p)}%"></div></div>
        <span class="mono text-xs">${p.toFixed(1)}%</span>
      </div>`
    }
    function memCell(c) {
      const pct = c.mem_limit ? Math.min(100, Math.round((c.mem_used / c.mem_limit) * 100)) : 0
      return `<div class="min-w-[132px]">
        <div class="flex items-center gap-2">
          <div class="meter" style="width:52px"><div class="meter-fill ${tone(pct, 85, 65)}" style="width:${pct}%"></div></div>
          <span class="mono text-xs">${fmtBytes(c.mem_used)}</span>
        </div>
        <div class="text-[10.5px] text-muted">/ ${fmtBytes(c.mem_limit)}</div>
      </div>`
    }
    function portsCell(c) {
      if (!c.ports || !c.ports.length) return '<span class="text-muted text-xs">—</span>'
      return '<div class="flex flex-col gap-0.5">' + c.ports.map(p => {
        const label = (p.published ? p.host + '→' : '') + p.container + '/' + p.proto
        return p.published
          ? `<span class="port"><a href="#" data-open-url aria-label="Open ${esc(label)}">${esc(label)}</a> ${icon('up-right-from-square')}</span>`
          : `<span class="port muted">${esc(label)}</span>`
      }).join('') + '</div>'
    }

    function stackDot(c) {
      const palette = ['#6366f1', '#0ea5e9', '#10b981', '#f59e0b', '#ec4899', '#8b5cf6', '#14b8a6']
      let h = 0; for (let i = 0; i < (c.stack || '').length; i++) h = (h * 31 + c.stack.charCodeAt(i)) % 997
      return `<span class="w-2 h-2 rounded-full inline-block shrink-0" style="background:${palette[h % palette.length]}" title="${esc(c.stack || 'no stack')}"></span>`
    }

    function rowActions(c) {
      if (c.state === 'running') {
        return `<button class="btn btn-xs btn-ghost" data-action="row-stop" data-id="${c.id}" title="Stop" aria-label="Stop ${esc(c.name)}">${icon('stop')}</button>
                <button class="btn btn-xs btn-ghost" data-action="row-restart" data-id="${c.id}" title="Restart" aria-label="Restart ${esc(c.name)}">${icon('rotate-right')}</button>`
      }
      if (c.state === 'paused') {
        return `<button class="btn btn-xs btn-ghost" data-action="row-unpause" data-id="${c.id}" title="Resume" aria-label="Resume ${esc(c.name)}">${icon('play')}</button>`
      }
      return `<button class="btn btn-xs btn-success" data-action="row-start" data-id="${c.id}" title="Start" aria-label="Start ${esc(c.name)}">${icon('play')}</button>`
    }

    function containersTable() {
      const list = filteredList()
      if (!list.length) {
        if (!state.containers.length) {
          return state.__forceEmpty
            ? emptyPanel('No containers running', 'The "Empty data" mock switch is on. Turn it off to restore the seeded fleet.', `<button class="btn btn-sm" data-action="toggle-empty">${icon('rotate-left')} Disable empty mode</button>`)
            : emptyPanel('No containers found', 'Deploy your first container to see it listed here.', `<button class="btn btn-sm btn-primary" data-action="run">${icon('plus')} Run container</button>`)
        }
        return emptyPanel('No matches', 'No container matches the current search / filters.', `<button class="btn btn-sm" data-action="clear-filters">${icon('filter-circle-xmark')} Clear filters</button>`)
      }

      return `
        <div class="card overflow-hidden">
          <div class="overflow-auto" style="max-height:calc(100vh - 400px)">
            <table class="table">
              <thead>
                <tr>
                  <th style="width:34px"><input type="checkbox" aria-label="Select all" id="select-all" ${state.selected.length === list.length && list.length ? 'checked' : ''} /></th>
                  <th>Name</th>
                  <th>State</th>
                  <th>Image</th>
                  <th>Ports</th>
                  <th>CPU</th>
                  <th>Memory</th>
                  <th>Net I/O</th>
                  <th class="num">Uptime</th>
                  <th style="width:150px">Actions</th>
                </tr>
              </thead>
              <tbody>
                ${list.map(c => {
                  const m = stateMeta(c)
                  const net = fmtBytes((c.net_rx || 0) + (c.net_tx || 0))
                  return `
                  <tr data-id="${c.id}" class="${state.selectedId === c.id ? 'selected' : ''}">
                    <td>
                      <input type="checkbox" data-check="${c.id}" aria-label="Select ${esc(c.name)}"
                             ${state.selected.includes(c.id) ? 'checked' : ''} />
                    </td>
                    <td style="min-width:230px">
                      <div class="flex items-center gap-2">
                        ${stackDot(c)}
                        <div class="min-w-0">
                          <div class="font-semibold flex items-center gap-1.5 truncate">
                            <span class="truncate" title="${esc(c.name)}">${esc(c.name)}</span>
                            ${c.sysbox ? '<span class="badge badge-xs badge-primary">sysbox</span>' : ''}
                          </div>
                          <div class="text-[11px] text-muted mono truncate">
                            ${esc(c.stack || '—')}${c.service ? ' / ' + esc(c.service) : ''} · ${c.short.slice(0, 8)}
                          </div>
                        </div>
                      </div>
                    </td>
                    <td>
                      <span class="badge badge-${m.key}"><span class="dot" style="background:${m.dot}"></span>${m.label}</span>
                      <div class="text-[10.5px] text-muted mt-1">${esc(c.status_text)}</div>
                    </td>
                    <td style="min-width:190px">
                      <div class="mono text-xs truncate" title="${esc(c.image)}">${esc(c.image)}</div>
                      <div class="text-[10.5px] text-muted mono">${c.image_id.slice(7, 19)}</div>
                    </td>
                    <td>${portsCell(c)}</td>
                    <td>${cpuCell(c)}</td>
                    <td>${memCell(c)}</td>
                    <td class="mono text-xs whitespace-nowrap">${net}</td>
                    <td class="num text-xs text-dim whitespace-nowrap">${c.state === 'running' ? fmtDuration(c.uptime_seconds) : '—'}</td>
                    <td>
                      <div class="flex items-center gap-1 justify-end" data-actions>
                        ${rowActions(c)}
                        <button class="btn btn-xs btn-ghost" data-action="row-logs" data-id="${c.id}" title="Logs" aria-label="Logs for ${esc(c.name)}">${icon('terminal')}</button>
                        <button class="btn btn-xs btn-ghost" data-action="row-menu" data-id="${c.id}" aria-label="More actions for ${esc(c.name)}" aria-haspopup="menu">${icon('ellipsis-vertical')}</button>
                      </div>
                    </td>
                  </tr>`
                }).join('')}
              </tbody>
            </table>
          </div>
        </div>`
    }

    function renderBulk() {
      const el = document.getElementById('bulk-bar')
      if (!el) return
      if (state.route !== 'containers' || !state.selected.length) { el.innerHTML = ''; return }
      el.innerHTML = `
        <div class="card card-pad mb-3 flex flex-wrap items-center gap-2" style="border-color:rgb(var(--primary)/.4)">
          <span class="text-sm font-semibold">${state.selected.length} selected</span>
          <div class="divider-v" style="height:20px"></div>
          <button class="btn btn-xs btn-success" data-action="bulk-start">${icon('play')} Start</button>
          <button class="btn btn-xs btn-warning" data-action="bulk-stop">${icon('stop')} Stop</button>
          <button class="btn btn-xs" data-action="bulk-restart">${icon('rotate-right')} Restart</button>
          <div class="grow"></div>
          <button class="btn btn-xs btn-ghost" data-action="bulk-clear">${icon('xmark')} Clear</button>
        </div>`
    }

    // ---- stacks ----
    function stacksView() {
      const list = filteredList()
      let n = 0
      state.summary && state.summary.counts
      if (!list.length) return emptyPanel('No compose stacks', 'Containers started outside a compose project are grouped under their own stack.')
      return `<div class="grid gap-3 grid-cols-1 lg:grid-cols-2 xl:grid-cols-3">` + list.map(s => {
        n++
        const badge = s.status === 'running' ? 'success' : s.status === 'degraded' ? 'warning' : 'neutral'
        return `
        <div class="card card-pad">
          <div class="flex items-start justify-between gap-2 mb-2">
            <div class="min-w-0">
              <div class="font-bold flex items-center gap-2">${icon('layer-group')} <span class="truncate">${esc(s.name)}</span></div>
              <div class="text-[11px] text-muted mono truncate" title="${esc(s.path)}">${esc(s.path)}</div>
            </div>
            <span class="badge badge-${badge}"><span class="dot"></span>${s.status}</span>
          </div>
          <div class="text-xs text-dim mb-2">${s.running}/${s.total} services running</div>
          <div class="flex flex-wrap gap-1 mb-3">
            ${s.services.map(sv => {
              const m = sv.state === 'running' ? (sv.health === 'unhealthy' ? 'error' : 'success') : sv.state === 'restarting' ? 'warning' : 'neutral'
              return `<button class="badge badge-xs badge-${m}" data-action="open-svc" data-id="${sv.id}" title="${esc(sv.name)}">${icon('cube')} ${esc(sv.service)}</button>`
            }).join('')}
          </div>
          <div class="flex flex-wrap gap-1 pt-2 border-t border-white/5">
            <button class="btn btn-xs" data-action="compose" data-op="up" data-stack="${esc(s.name)}">${icon('play')} Up</button>
            <button class="btn btn-xs" data-action="compose" data-op="restart" data-stack="${esc(s.name)}">${icon('rotate-right')} Restart</button>
            <button class="btn btn-xs btn-error" data-action="compose" data-op="down" data-stack="${esc(s.name)}">${icon('stop')} Down</button>
            <div class="grow"></div>
            <button class="btn btn-xs btn-ghost" data-action="compose-logs" data-stack="${esc(s.name)}">${icon('terminal')} Compose logs</button>
          </div>
        </div>`
      }).join('') + '</div>'
    }

    // ---- images ----
    function imagesTable() {
      const list = filteredList()
      if (!list.length) return emptyPanel('No images', 'Images pulled by your containers will appear here.')
      return `
        <div class="card overflow-hidden">
          <div class="overflow-auto" style="max-height:calc(100vh - 400px)">
            <table class="table">
              <thead><tr>
                <th>Repository:Tag</th><th>Image ID</th><th class="num">Size</th><th>Created</th>
                <th class="num">Used by</th><th style="width:120px">Actions</th>
              </tr></thead>
              <tbody>
                ${list.map(i => `
                  <tr data-id="${i.id}">
                    <td>
                      <div class="flex items-center gap-2">
                        ${icon('box-archive')}
                        <span class="mono text-xs">${esc(i.repo)}<span class="text-muted">:${esc(i.tag)}</span></span>
                        ${i.dangling ? '<span class="badge badge-xs badge-warning">dangling</span>' : ''}
                      </div>
                    </td>
                    <td class="mono text-[11px] text-muted">${i.id.slice(7, 19)}</td>
                    <td class="num mono text-xs">${fmtBytes(i.size)}</td>
                    <td class="text-xs text-dim">${timeAgo(i.created)}</td>
                    <td class="num"><span class="badge badge-xs badge-neutral">${i.containers}</span></td>
                    <td>
                      <div class="flex justify-end gap-1" data-actions>
                        <button class="btn btn-xs btn-ghost" data-action="img-inspect" data-id="${i.id}" title="Inspect" aria-label="Inspect image">${icon('code')}</button>
                        <button class="btn btn-xs btn-error" data-action="img-remove" data-id="${i.id}" title="Remove" aria-label="Remove image">${icon('trash')}</button>
                      </div>
                    </td>
                  </tr>`).join('')}
              </tbody>
            </table>
          </div>
        </div>
        <div class="flex justify-end mt-3">
          <button class="btn btn-sm btn-error btn-outline" data-action="img-prune">${icon('broom')} Prune dangling images</button>
        </div>`
    }

    // ---- volumes ----
    function volumesTable() {
      const list = filteredList()
      if (!list.length) return emptyPanel('No volumes', 'Named and anonymous volumes will appear here.')
      return `
        <div class="card overflow-hidden">
          <div class="overflow-auto" style="max-height:calc(100vh - 400px)">
            <table class="table">
              <thead><tr>
                <th>Name</th><th>Driver</th><th class="num">Size</th><th>Stack</th><th>In use</th><th>Mountpoint</th>
                <th style="width:120px">Actions</th>
              </tr></thead>
              <tbody>
                ${list.map(v => `
                  <tr data-id="${v.name}">
                    <td>
                      <div class="flex items-center gap-2">
                        ${icon('database')}
                        <span class="mono text-xs ${v.anonymous ? 'text-muted' : ''}" title="${esc(v.name)}">${v.anonymous ? v.name.slice(0, 12) : esc(v.name)}</span>
                        ${v.anonymous ? '<span class="badge badge-xs badge-neutral">anon</span>' : ''}
                      </div>
                    </td>
                    <td class="text-xs text-dim">${esc(v.driver)}</td>
                    <td class="num mono text-xs">${fmtBytes(v.size)}</td>
                    <td class="text-xs text-dim">${esc(v.stack || '—')}</td>
                    <td>${v.in_use
                      ? '<span class="badge badge-xs badge-success"><span class="dot"></span>in use</span>'
                      : '<span class="badge badge-xs badge-neutral">unused</span>'}</td>
                    <td class="mono text-[11px] text-muted truncate" style="max-width:320px" title="${esc(v.mountpoint)}">${esc(v.mountpoint)}</td>
                    <td>
                      <div class="flex justify-end gap-1" data-actions>
                        <button class="btn btn-xs btn-ghost" data-action="vol-copy" data-id="${esc(v.mountpoint)}" title="Copy mountpoint" aria-label="Copy mountpoint">${icon('copy')}</button>
                        <button class="btn btn-xs btn-error" data-action="vol-remove" data-id="${esc(v.name)}" data-used="${v.in_use}" title="Remove" aria-label="Remove volume">${icon('trash')}</button>
                      </div>
                    </td>
                  </tr>`).join('')}
              </tbody>
            </table>
          </div>
        </div>
        <div class="flex justify-end mt-3">
          <button class="btn btn-sm btn-error btn-outline" data-action="vol-prune">${icon('broom')} Prune unused volumes</button>
        </div>`
    }

    // ---- networks ----
    function networksTable() {
      const list = filteredList()
      if (!list.length) return emptyPanel('No networks', 'Bridge, host and overlay networks will appear here.')
      return `
        <div class="card overflow-hidden">
          <div class="overflow-auto" style="max-height:calc(100vh - 400px)">
            <table class="table">
              <thead><tr>
                <th>Name</th><th>Driver</th><th>Scope</th><th>Subnet</th><th class="num">Attached</th><th>Containers</th>
              </tr></thead>
              <tbody>
                ${list.map(n => `
                  <tr data-id="${n.id}">
                    <td><div class="flex items-center gap-2">${icon('network-wired')} <span class="mono text-xs">${esc(n.name)}</span>
                      ${n.internal ? '<span class="badge badge-xs badge-neutral">internal</span>' : ''}</div></td>
                    <td class="text-xs text-dim">${esc(n.driver)}</td>
                    <td class="text-xs text-dim">${esc(n.scope)}</td>
                    <td class="mono text-xs">${esc(n.subnet)}</td>
                    <td class="num"><span class="badge badge-xs badge-neutral">${n.containers.length}</span></td>
                    <td class="text-xs text-muted">${n.containers.length ? n.containers.map(esc).join(', ') : '—'}</td>
                  </tr>`).join('')}
              </tbody>
            </table>
          </div>
        </div>`
    }

    // ---- events ----
    function eventsView() {
      const list = filteredList()
      const color = { start: 'success', create: 'info', restart: 'warning', die: 'error', destroy: 'error', kill: 'error', unhealthy: 'error', pull: 'primary', up: 'success', down: 'neutral' }
      if (!list.length) return emptyPanel('No events', 'Docker daemon events will stream here as they happen.')
      return `
        <div class="card">
          <div class="card-pad flex items-center gap-2 text-sm">
            ${icon('bolt')} <b>${list.length}</b> recent events
            <span class="badge badge-xs badge-neutral ml-1">live stream · mock</span>
          </div>
          <div class="line-h"></div>
          <div class="scroll-y" style="max-height:calc(100vh - 420px)">
            ${list.map(e => `
              <div class="flex items-center gap-3 px-4 py-2.5 border-b border-white/5">
                <span class="w-16 shrink-0 text-[11px] mono text-muted">${fmtTime(e.ts).slice(11)}</span>
                <span class="badge badge-xs badge-${color[e.action] || 'neutral'}">${esc(e.action)}</span>
                <span class="text-xs text-dim">${esc(e.type)}</span>
                <span class="grow text-[12.5px] truncate mono">${esc(e.actor)}</span>
                <span class="text-[11px] text-muted shrink-0">${timeAgo(e.ts)}</span>
              </div>`).join('')}
          </div>
        </div>`
    }

    /* =======================================================================
       G. DRAWER (container detail)
       ======================================================================= */
    function renderDrawer() {
      const root = document.getElementById('drawer-root')
      if (!root) return
      const c = state.selectedId ? findContainer(state.selectedId) : null
      const open = !!c

      const tabs = ['overview', 'stats', 'logs', 'inspect', 'volumes', 'networks', 'env']
      const tabIcon = { overview: 'circle-info', stats: 'chart-simple', logs: 'terminal', inspect: 'code', volumes: 'database', networks: 'network-wired', env: 'list' }

      root.innerHTML = `
        <div class="drawer-backdrop ${open ? 'open' : ''}" data-action="close-drawer"></div>
        <aside class="drawer ${open ? 'open' : ''}" role="dialog" aria-modal="true" aria-label="Container details" ${open ? '' : 'hidden'}>
          ${!c ? '' : `
          <div class="flex items-start gap-3 p-4 border-b border-white/10">
            <span class="grid place-items-center w-9 h-9 rounded-lg shrink-0" style="background:rgb(var(--primary)/.14);color:#a5b4fc">${icon('cube')}</span>
            <div class="min-w-0 grow">
              <div class="font-bold truncate" title="${esc(c.name)}">${esc(c.name)}</div>
              <div class="text-[11.5px] text-muted mono truncate">${c.short} · ${esc(c.image)}</div>
            </div>
            <button class="btn btn-xs btn-ghost" data-action="close-drawer" aria-label="Close details">${icon('xmark')}</button>
          </div>

          <div class="flex items-center gap-2 px-4 py-2 border-b border-white/10 flex-wrap">
            <span class="badge badge-${stateMeta(c).key}"><span class="dot"></span>${stateMeta(c).label}</span>
            <span class="text-[11.5px] text-muted">${esc(c.status_text)}</span>
            <div class="grow"></div>
            ${c.state === 'running'
              ? `<button class="btn btn-xs btn-warning" data-action="d-stop" data-id="${c.id}">${icon('stop')} Stop</button>
                 <button class="btn btn-xs" data-action="d-restart" data-id="${c.id}">${icon('rotate-right')} Restart</button>`
              : `<button class="btn btn-xs btn-success" data-action="d-start" data-id="${c.id}">${icon('play')} Start</button>`}
            <button class="btn btn-xs btn-error" data-action="d-delete" data-id="${c.id}" aria-label="Remove container">${icon('trash')}</button>
          </div>

          <div class="tabs px-2" role="tablist">
            ${tabs.map(t => `<button class="tab ${state.drawerTab === t ? 'active' : ''}" data-drawer-tab="${t}" role="tab" aria-selected="${state.drawerTab === t}">
              ${icon(tabIcon[t])} ${t[0].toUpperCase() + t.slice(1)}</button>`).join('')}
          </div>

          <div class="scroll-y grow p-4">${drawerBody(c)}</div>
          `}
        </aside>`
    }

    function drawerBody(c) {
      switch (state.drawerTab) {
        case 'stats': return drawerStats(c)
        case 'logs': return drawerLogs(c)
        case 'inspect': return drawerInspect(c)
        case 'volumes': return drawerVolumes(c)
        case 'networks': return drawerNetworks(c)
        case 'env': return drawerEnv(c)
        default: return drawerOverview(c)
      }
    }

    function defRow(k, v) {
      return `<div class="flex gap-3 py-2 border-b border-white/5">
        <div class="w-36 shrink-0 text-[12px] text-dim">${k}</div>
        <div class="text-[12.5px] min-w-0 break-words grow">${v}</div>
      </div>`
    }

    function drawerOverview(c) {
      return `
        <div class="card mb-3">
          <div class="card-pad">
            ${defRow('State', `<span class="badge badge-${stateMeta(c).key}">${stateMeta(c).label}</span> <span class="text-muted">· ${esc(c.status_text)}</span>`)}
            ${defRow('Host', esc((DB.hosts.find(h => h.id === c.host_id) || {}).name || c.host_id))}
            ${defRow('Stack / Service', esc(c.stack || '—') + (c.service ? ' / ' + esc(c.service) : ''))}
            ${defRow('Image', `<span class="mono">${esc(c.image)}</span>`)}
            ${defRow('Container ID', `<span class="mono">${c.short}</span> <button class="btn btn-xs btn-ghost" data-action="copy" data-copy="${c.id}" aria-label="Copy id">${icon('copy')}</button>`)}
            ${defRow('Created', fmtTime(c.created) + ' <span class="text-muted">(' + timeAgo(c.created) + ')</span>')}
            ${defRow('Started', c.state === 'running' || c.state === 'paused' ? fmtTime(c.started_at) + ' <span class="text-muted">(' + fmtDuration(c.uptime_seconds) + ')</span>' : '—')}
            ${defRow('Restart policy', `${esc(c.restart_policy)} <span class="text-muted">· restarts: ${c.restart_count || 0}</span>`)}
            ${defRow('Ports', c.ports && c.ports.length ? c.ports.map(p => `<span class="port ${p.published ? '' : 'muted'}">${p.published ? p.host + '→' : ''}${p.container}/${p.proto}</span>`).join(' ') : '—')}
            ${defRow('URL', c.url ? `<a class="port" href="#" data-open-url>${icon('up-right-from-square')} ${esc(c.url)}</a>` : '—')}
            ${defRow('CPU / PIDs', `${(c.cpu_pct || 0).toFixed(1)}% · ${c.pids || 0} pids`)}
            ${defRow('Memory', `${fmtBytes(c.mem_used)} / ${fmtBytes(c.mem_limit)}`)}
            ${defRow('Entrypoint', c.entrypoint ? `<span class="mono text-[11.5px]">${esc(c.entrypoint)}</span>` : '—')}
            ${defRow('Command', c.cmd && c.cmd.length ? `<span class="mono text-[11.5px]">${esc(c.cmd.join(' '))}</span>` : '—')}
            ${c.healthcheck ? defRow('Healthcheck', `<span class="mono text-[11.5px]">${esc(c.healthcheck.test)} · every ${esc(c.healthcheck.interval)} · retries ${c.healthcheck.retries}</span>`) : ''}
            ${c.sysbox ? defRow('Runtime', '<span class="badge badge-xs badge-primary">sysbox</span>') : ''}
          </div>
        </div>

        ${Object.keys(c.labels || {}).length ? `
        <div class="card card-pad">
          <div class="font-semibold text-sm mb-2">${icon('tags')} Labels</div>
          ${Object.entries(c.labels).map(([k, v]) => defRow(`<span class="mono">${esc(k)}</span>`, `<span class="mono text-[11.5px]">${esc(v)}</span>`)).join('')}
        </div>` : ''}
      `
    }

    function drawerStats(c) {
      if (state.drawer.loadingStats) return skeletonBlock()
      const st = state.drawer.stats
      if (!st) return `<div class="text-dim text-sm">No stats available.</div>`
      const cpu = st.series.map(s => s.cpu)
      const mem = st.series.map(s => (s.mem / (st.current.mem_limit || 1)) * 100)
      const cur = st.current
      const memPct = cur.mem_limit ? Math.round((cur.mem_used / cur.mem_limit) * 100) : 0
      return `
        <div class="grid grid-cols-2 gap-3 mb-3">
          <div class="card card-pad">
            <div class="text-[11px] uppercase tracking-wide text-muted mb-1">CPU</div>
            <div class="text-2xl font-bold">${(cur.cpu_pct).toFixed(1)}<span class="text-sm text-dim">%</span></div>
            <div class="bars mt-3">${cpu.map(v => `<span class="${v >= 70 ? 'error' : v >= 40 ? 'warning' : ''}" style="height:${Math.max(4, Math.min(100, v))}%"></span>`).join('')}</div>
            <div class="text-[10.5px] text-muted mt-1">last 60 minutes</div>
          </div>
          <div class="card card-pad">
            <div class="text-[11px] uppercase tracking-wide text-muted mb-1">Memory</div>
            <div class="text-2xl font-bold">${memPct}<span class="text-sm text-dim">%</span></div>
            <div class="bars mt-3">${mem.map(v => `<span class="${v >= 85 ? 'error' : v >= 65 ? 'warning' : ''}" style="height:${Math.max(4, Math.min(100, v))}%"></span>`).join('')}</div>
            <div class="text-[10.5px] text-muted mt-1">${fmtBytes(cur.mem_used)} / ${fmtBytes(cur.mem_limit)}</div>
          </div>
        </div>
        <div class="card card-pad">
          ${defRow('Network I/O', `RX ${fmtBytes(cur.net_rx)} · TX ${fmtBytes(cur.net_tx)}`)}
          ${defRow('Block I/O', `Read ${fmtBytes(cur.block_read)} · Write ${fmtBytes(cur.block_write)}`)}
          ${defRow('PIDs', String(cur.pids))}
          ${defRow('Sample', '1s interval · aggregated over 60s window (mock)')}
        </div>`
    }

    function drawerLogs(c) {
      const toolbar = `
        <div class="flex items-center gap-2 mb-3">
          <label class="sr-only" for="log-tail">Tail</label>
          <select class="select input-sm" id="log-tail" style="width:auto">
            ${[50, 120, 200].map(n => `<option value="${n}" ${state.drawer.tail === n ? 'selected' : ''}>tail ${n}</option>`).join('')}
          </select>
          <label class="switch"><input type="checkbox" checked disabled role="switch" /><span class="track"></span><span>Follow</span></label>
          <div class="grow"></div>
          <button class="btn btn-xs btn-ghost" data-action="log-refresh" aria-label="Refresh logs">${icon('arrows-rotate')} Refresh</button>
          <button class="btn btn-xs btn-ghost" data-action="log-download" aria-label="Download logs">${icon('download')}</button>
        </div>`
      if (state.drawer.loadingLogs) return toolbar + skeletonBlock()
      const lines = state.drawer.logs || []
      if (!lines.length) return toolbar + `<div class="text-dim text-sm">No log output.</div>`
      return toolbar + `
        <div class="card p-3 mono" style="background:rgb(var(--bg))">
          ${lines.map(l => `<div class="log-line">
            <span class="ts">${fmtTime(l.ts).slice(11)}</span>
            <span class="lv lv-${l.level}">${l.level}</span>
            <span class="msg">${esc(l.msg)}</span>
          </div>`).join('')}
        </div>`
    }

    function drawerInspect(c) {
      const payload = {
        Id: c.id, Name: '/' + c.name, Created: c.created, Image: c.image,
        State: { Status: c.state, Health: c.health ? { Status: c.health } : undefined, RestartCount: c.restart_count || 0, StartedAt: c.started_at },
        HostConfig: { RestartPolicy: { Name: c.restart_policy }, PortBindings: c.ports },
        Config: { Image: c.image, Env: c.env.map(e => e.k + '=' + e.v), Cmd: c.cmd, Labels: c.labels, Healthcheck: c.healthcheck },
        Mounts: c.mounts,
        NetworkSettings: { Networks: c.networks.reduce((a, n) => (a[n.name] = { IPAddress: n.ip }, a), {}) }
      }
      return `
        <div class="flex items-center justify-between mb-2">
          <span class="text-xs text-dim">docker inspect (trimmed)</span>
          <button class="btn btn-xs btn-ghost" data-action="copy" data-copy='${esc(JSON.stringify(payload))}' >${icon('copy')} Copy JSON</button>
        </div>
        <pre class="card p-3 mono text-[11.5px] overflow-auto" style="max-height:calc(100vh - 320px)">${esc(JSON.stringify(payload, null, 2))}</pre>`
