    function drawerVolumes(c) {
      if (!c.mounts || !c.mounts.length) return `<div class="text-dim text-sm">No volumes or bind mounts.</div>`
      return `<div class="card overflow-hidden"><table class="table"><thead><tr>
        <th>Type</th><th>Source</th><th>Destination</th><th>Mode</th></tr></thead><tbody>
        ${c.mounts.map(m => `<tr>
          <td><span class="badge badge-xs badge-neutral">${esc(m.type)}</span></td>
