          <td class="mono text-[11.5px]">${esc(m.destination)}</td>
          <td class="text-xs text-dim">${esc(m.mode)}</td>
        </tr>`).join('')}
      </tbody></table></div>`
    }

    function drawerNetworks(c) {
      if (!c.networks || !c.networks.length) return `<div class="text-dim text-sm">Not attached to any network.</div>`
      return `<div class="card overflow-hidden"><table class="table"><thead><tr>
        <th>Network</th><th>IP address</th></tr></thead><tbody>
        ${c.networks.map(n => `<tr>
          <td class="mono text-xs">${icon('network-wired')} ${esc(n.name)}</td>
          <td class="mono text-xs">${esc(n.ip || '—')}</td>
        </tr>`).join('')}
      </tbody></table></div>`
    }

    function drawerEnv(c) {
      if (!c.env || !c.env.length) return `<div class="text-dim text-sm">No environment variables.</div>`
      return `<div class="card overflow-hidden"><table class="table"><tbody>
        ${c.env.map(e => `<tr style="cursor:default">
          <td class="mono text-xs text-dim" style="width:38%">${esc(e.k)}</td>
          <td class="mono text-xs break-all">${esc(e.v)}</td>
        </tr>`).join('')}
      </tbody></table></div>`
    }

    function skeletonBlock() {
      return `<div class="space-y-2">
        ${Array.from({ length: 6 }).map(() => '<div class="skeleton" style="height:14px;width:' + (60 + Math.round(Math.random() * 35)) + '%"></div>').join('')}
      </div>`
    }

    /* =======================================================================
       H. MENU / MODAL / TOASTS / MOCK PANEL
       ======================================================================= */
    function renderMenu() {
      let el = document.getElementById('menu-root')
      if (!state.menu) { if (el) el.remove(); return }
      const c = findContainer(state.menu.id)
      if (!c) { state.menu = null; if (el) el.remove(); return }
      if (!el) { el = document.createElement('div'); el.id = 'menu-root'; document.body.appendChild(el) }

      const running = c.state === 'running'
      el.innerHTML = `
        <div class="menu-pop" role="menu" style="left:${state.menu.x}px;top:${state.menu.y}px" data-menu>
          <button class="menu-item" role="menuitem" data-action="row-details" data-id="${c.id}">${icon('circle-info')} View details</button>
          <button class="menu-item" role="menuitem" data-action="row-stats" data-id="${c.id}">${icon('chart-simple')} Resource stats</button>
          <button class="menu-item" role="menuitem" data-action="row-logs" data-id="${c.id}">${icon('terminal')} Logs</button>
          <button class="menu-item" role="menuitem" data-action="row-exec" data-id="${c.id}">${icon('keyboard')} Open shell (exec)</button>
          ${c.url ? `<button class="menu-item" role="menuitem" data-action="row-open" data-id="${c.id}">${icon('up-right-from-square')} Open in browser</button>` : ''}
          <div class="menu-sep"></div>
          ${running
            ? `<button class="menu-item" role="menuitem" data-action="row-pause" data-id="${c.id}">${icon('pause')} Pause</button>
               <button class="menu-item" role="menuitem" data-action="row-restart" data-id="${c.id}">${icon('rotate-right')} Restart</button>`
            : `<button class="menu-item" role="menuitem" data-action="row-start" data-id="${c.id}">${icon('play')} Start</button>`}
          <button class="menu-item" role="menuitem" data-action="row-inspect" data-id="${c.id}">${icon('code')} Inspect (JSON)</button>
          <button class="menu-item" role="menuitem" data-action="row-copyid" data-id="${c.id}">${icon('copy')} Copy container ID</button>
          <div class="menu-sep"></div>
          <button class="menu-item danger" role="menuitem" data-action="row-remove" data-id="${c.id}">${icon('trash')} Remove container…</button>
        </div>`
    }

    function renderModal() {
      const root = document.getElementById('modal-root')
      if (!root) return
      const m = state.modal
      if (!m) { root.innerHTML = ''; return }

      if (m.type === 'confirm') {
        root.innerHTML = `
          <div class="modal" data-modal-backdrop>
            <div class="modal-box" role="dialog" aria-modal="true" aria-labelledby="modal-title">
              <div class="p-5">
                <h3 class="font-bold text-lg flex items-center gap-2" id="modal-title">
                  <span class="${m.danger ? 'text-error' : 'text-primary'}">${icon(m.danger ? 'triangle-exclamation' : 'circle-question')}</span>
                  ${esc(m.title)}
                </h3>
                <p class="text-dim text-sm mt-2">${m.html}</p>
              </div>
              <div class="flex justify-end gap-2 p-4 border-t border-white/10">
                <button class="btn btn-sm btn-ghost" data-action="modal-cancel">${esc(m.cancelText)}</button>
                <button class="btn btn-sm ${m.danger ? 'btn-error' : 'btn-primary'}" data-action="modal-confirm">${esc(m.confirmText)}</button>
              </div>
            </div>
          </div>`
        return
      }

      if (m.type === 'json') {
        root.innerHTML = `
          <div class="modal" data-modal-backdrop>
            <div class="modal-box" role="dialog" aria-modal="true" style="max-width:680px">
              <div class="flex items-center justify-between p-4 border-b border-white/10">
                <h3 class="font-bold flex items-center gap-2">${icon('code')} ${esc(m.title)}</h3>
                <button class="btn btn-xs btn-ghost" data-action="modal-close" aria-label="Close">${icon('xmark')}</button>
              </div>
              <pre class="p-4 mono text-[11.5px] overflow-auto scroll-y grow" style="max-height:60vh">${esc(m.json)}</pre>
              <div class="flex justify-end p-3 border-t border-white/10">
                <button class="btn btn-sm btn-ghost" data-action="modal-close">Close</button>
              </div>
            </div>
          </div>`
        return
      }

      if (m.type === 'run') {
        const f = m.form, e = m.errors || {}
        const field = (id, label, ph, val, err, hint) => `
          <div class="mb-3">
            <label class="block text-[12.5px] text-dim mb-1" for="${id}">${label}</label>
            <input id="${id}" class="input ${err ? 'invalid' : ''}" placeholder="${ph}" value="${esc(val)}" data-run-field="${id.replace('run-', '')}" />
            ${err ? `<div class="field-error">${esc(err)}</div>` : (hint ? `<div class="text-[11px] text-muted mt-1">${hint}</div>` : '')}
          </div>`
        root.innerHTML = `
          <div class="modal" data-modal-backdrop>
            <div class="modal-box" role="dialog" aria-modal="true" aria-labelledby="modal-title">
              <div class="flex items-center justify-between p-4 border-b border-white/10">
                <h3 class="font-bold flex items-center gap-2" id="modal-title">${icon('play')} Run a new container</h3>
                <button class="btn btn-xs btn-ghost" data-action="modal-close" aria-label="Close">${icon('xmark')}</button>
              </div>
              <div class="p-4 scroll-y" style="max-height:64vh">
                ${field('run-name', 'Container name *', 'e.g. my-worker', f.name, e.name)}
                ${field('run-image', 'Image *', 'e.g. redis:7-alpine', f.image, e.image)}
                ${field('run-ports', 'Port mappings', '8001:8001, 9000:9000', f.ports, e.ports, 'Comma separated host:container mappings')}
                ${field('run-env', 'Environment variables', 'NODE_ENV=production, PORT=3000', f.env, e.env, 'Comma or newline separated KEY=VALUE')}
                ${field('run-cmd', 'Command (optional)', 'node server.js', f.cmd, e.cmd)}
              </div>
              <div class="flex justify-end gap-2 p-4 border-t border-white/10">
                <button class="btn btn-sm btn-ghost" data-action="modal-close">Cancel</button>
                <button class="btn btn-sm btn-primary" data-action="run-submit" ${m.submitting ? 'disabled' : ''}>
                  ${m.submitting ? icon('spinner') + ' spinning' : icon('play')} ${m.submitting ? 'Starting…' : 'Run container'}
                </button>
              </div>
            </div>
          </div>`
        return
      }
    }

    function renderToasts() {
      const el = document.getElementById('toast-root')
      if (!el) return
      el.innerHTML = state.toasts.map(t => {
        const ic = t.kind === 'success' ? 'circle-check' : t.kind === 'error' ? 'circle-xmark' : t.kind === 'warning' ? 'triangle-exclamation' : 'circle-info'
        return `<div class="toast ${t.kind}" role="status">
          <span class="${{ success: 'text-success', error: 'text-error', warning: 'text-warning' }[t.kind] || 'text-primary'}">${icon(ic)}</span>
          <span class="text-[12.5px] grow">${esc(t.text)}</span>
          <button class="btn btn-xs btn-ghost" data-action="toast-close" data-id="${t.id}" aria-label="Dismiss">${icon('xmark')}</button>
        </div>`
      }).join('')
    }

    function renderMockPanel() {
      const el = document.getElementById('mock-controls')
      if (!el) return
      if (!state.mockPanelOpen) {
        el.innerHTML = `<button class="btn btn-sm btn-warning" data-action="mock-toggle" title="Mock controls">${icon('flask')} Mock</button>`
        return
      }
      el.innerHTML = `
        <div class="mock-panel">
          <div class="flex items-center gap-2 mb-2">
            <span class="badge badge-xs badge-warning">MOCK</span>
            <span class="text-[12px] font-semibold">Mock controls</span>
            <div class="grow"></div>
            <button class="btn btn-xs btn-ghost" data-action="mock-toggle" aria-label="Collapse">${icon('xmark')}</button>
          </div>
          <label class="switch w-full mb-1"><input type="checkbox" id="mock-fail" role="switch" ${state.__forceFail ? 'checked' : ''} /><span class="track"></span><span>Fail next request (500)</span></label>
          <label class="switch w-full mb-1"><input type="checkbox" id="mock-empty" role="switch" ${state.__forceEmpty ? 'checked' : ''} /><span class="track"></span><span>Empty container list</span></label>
          <div class="line-h my-2"></div>
          <button class="btn btn-xs btn-block btn-error btn-outline" data-action="reset-mock">${icon('broom')} Reset mock data</button>
          <p class="text-[10.5px] text-muted mt-2 leading-relaxed">
            All data comes from the in-file <code class="k">mockFetch()</code> layer — no network calls.
          </p>
        </div>`
    }

    /* =======================================================================
       I. DATA LOADING
       ======================================================================= */
    async function refreshSummary() {
      try {
        // MOCK: jitter the host gauges a little each refresh so it feels alive
        const host = DB.hosts.find(h => h.id === state.hostId)
        if (host) {
          host.cpu_pct = Math.max(2, Math.min(98, +(host.cpu_pct + (rnd() - 0.5) * 4).toFixed(1)))
          host.mem_used = Math.max(GiB, Math.min(host.mem_total, host.mem_used + (rnd() - 0.5) * GiB * 0.4))
        }
        state.summary = await apiGet('/api/infra/summary?host=' + state.hostId)
      } catch (e) { /* summary is best-effort */ }
    }

    async function loadAll() {
      state.status = 'loading'; state.error = null
      render()
      try {
        const host = state.hostId
        const [summary, containers, stacks, images, volumes, networks, events] = await Promise.all([
          apiGet('/api/infra/summary?host=' + host),
          apiGet('/api/infra/containers?host=' + host),
          apiGet('/api/infra/stacks?host=' + host),
          apiGet('/api/infra/images?host=' + host),
          apiGet('/api/infra/volumes?host=' + host),
          apiGet('/api/infra/networks?host=' + host),
          apiGet('/api/infra/events?host=' + host)
        ])
        state.summary = summary
        state.containers = containers.containers
        state.stacks = stacks.stacks
        state.images = images.images
        state.volumes = volumes.volumes
        state.networks = networks.networks
        state.events = events.events
        state.status = 'ready'
        state.lastUpdated = new Date()
      } catch (e) {
        state.status = 'error'
        state.error = e.message
      }
      render()
    }

    async function reloadCurrentTab() {
      const host = state.hostId
      try {
        if (state.route === 'containers') state.containers = (await apiGet('/api/infra/containers?host=' + host)).containers
        else if (state.route === 'stacks') state.stacks = (await apiGet('/api/infra/stacks?host=' + host)).stacks
        else if (state.route === 'images') state.images = (await apiGet('/api/infra/images?host=' + host)).images
        else if (state.route === 'volumes') state.volumes = (await apiGet('/api/infra/volumes?host=' + host)).volumes
        else if (state.route === 'networks') state.networks = (await apiGet('/api/infra/networks?host=' + host)).networks
        else if (state.route === 'events') state.events = (await apiGet('/api/infra/events?host=' + host)).events
      } catch (e) { toast(e.message, 'error') }
    }

    // MOCK: fake "live" tick — nudges CPU/mem so the view feels streaming
    function startLive() {
      stopLive()
      state._timer = setInterval(async () => {
        DB.containers.filter(c => c.host_id === state.hostId && c.state === 'running').forEach(c => {
          c.cpu_pct = Math.max(0, Math.min(99, +(c.cpu_pct + (rnd() - 0.5) * Math.max(0.3, c.cpu_pct * 0.2)).toFixed(1)))
          c.mem_used = Math.max(8 * MiB, Math.min(c.mem_limit, c.mem_used + (rnd() - 0.5) * c.mem_limit * 0.01))
          c.mem_pct = c.mem_limit ? Math.round(c.mem_used / c.mem_limit * 100) : 0
        })
        await refreshSummary()
        const list = state.containers.map(c => Object.assign({}, findContainer(c.id) || c))
        state.containers = list
        state.lastUpdated = new Date()
        if (state.route === 'containers') renderResults()
        renderHostStrip()
        const lu = document.getElementById('last-updated')
        if (lu) lu.textContent = 'Updated ' + fmtTime(state.lastUpdated.toISOString())
      }, 3000)
    }
    function stopLive() { if (state._timer) { clearInterval(state._timer); state._timer = null } }

    /* =======================================================================
       J. EVENTS (delegation + wiring)
       ======================================================================= */
    function copyText(text) {
      const done = () => toast('Copied to clipboard', 'success')
      if (navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard.writeText(text).then(done).catch(() => toast('Copy blocked by browser', 'warning'))
      } else {
        const ta = document.createElement('textarea')
        ta.value = text; document.body.appendChild(ta); ta.select()
        try { document.execCommand('copy'); done() } catch (e) { toast('Copy not supported', 'warning') }
        ta.remove()
      }
    }

    function refreshAllViews() { renderResults(); renderDrawer(); renderHostStrip(); renderTabs() }

    async function handleAction(action, el) {
      const id = el.getAttribute('data-id')
      switch (action) {
        /* ---- app-level ---- */
        case 'reload': loadAll(); break
        case 'run': openRunModal(); break
        case 'clear-filters':
          state.filters.q = ''; state.filters.state = 'all'; state.filters.stack = 'all'
          persistState(); renderTab()
          break
        case 'toggle-empty':
          state.__forceEmpty = false; renderMockPanel(); loadAll()
          break
        case 'reset-mock': resetMock(); break
        case 'mock-toggle': state.mockPanelOpen = !state.mockPanelOpen; renderMockPanel(); break
        case 'toast-close':
          state.toasts = state.toasts.filter(t => t.id !== id); renderToasts(); break

        /* ---- selection ---- */
        case 'bulk-start': bulkAction('start'); break
        case 'bulk-stop': bulkAction('stop'); break
        case 'bulk-restart': bulkAction('restart'); break
        case 'bulk-clear': state.selected = []; renderResults(); break

        /* ---- row actions ---- */
        case 'row-start': containerAction(id, 'start'); break
        case 'row-stop': containerAction(id, 'stop'); break
        case 'row-restart': containerAction(id, 'restart'); break
        case 'row-pause': containerAction(id, 'pause'); break
        case 'row-unpause': containerAction(id, 'unpause'); break
        case 'row-logs': closeMenu(); openDrawer(id, 'logs'); break
        case 'row-stats': closeMenu(); openDrawer(id, 'stats'); break
        case 'row-details': closeMenu(); openDrawer(id, 'overview'); break
        case 'row-inspect': {
          closeMenu()
          const c = findContainer(id)
          state.modal = { type: 'json', title: 'Inspect · ' + (c ? c.name : id), json: JSON.stringify(c, null, 2) }
          renderModal()
          break
        }
        case 'row-exec':
          closeMenu()
          toast('Running: docker exec -it ' + (findContainer(id) || {}).name + ' /bin/sh (mocked)', 'info')
          break
        case 'row-open': {
          closeMenu()
          const c = findContainer(id)
          toast('Opening ' + (c && c.url ? c.url : 'container') + ' (mocked)', 'info')
          break
        }
        case 'row-copyid': copyText((findContainer(id) || {}).id || id); closeMenu(); break
        case 'row-menu': openMenu({ currentTarget: el, stopPropagation: () => {} }, id); break
        case 'row-remove': closeMenu(); deleteContainer(id); break

        /* ---- drawer ---- */
        case 'close-drawer': closeDrawer(); break
        case 'd-start': containerAction(id, 'start'); break
        case 'd-stop': containerAction(id, 'stop'); break
        case 'd-restart': containerAction(id, 'restart'); break
        case 'd-delete': deleteContainer(id); break
        case 'log-refresh': loadLogs(state.selectedId); break
        case 'log-download': toast('Downloading logs for ' + ((findContainer(state.selectedId) || {}).name) + ' (mocked)', 'info'); break

        /* ---- images ---- */
        case 'img-inspect': {
          const img = state.images.find(i => i.id === id)
          state.modal = { type: 'json', title: 'Inspect image', json: JSON.stringify(img, null, 2) }
          renderModal(); break
        }
        case 'img-remove': {
          const img = state.images.find(i => i.id === id)
          if (img && img.containers > 0) { toast('Image is in use by ' + img.containers + ' container(s) — cannot remove', 'error'); break }
          state.images = state.images.filter(i => i.id !== id)
          toast('Image removed', 'success')
          renderResults(); renderTabs()
          break
        }
        case 'img-prune': {
          const dangling = state.images.filter(i => i.dangling)
          state.images = state.images.filter(i => !i.dangling)
          toast('Pruned ' + dangling.length + ' dangling image(s)', 'success')
          renderResults(); renderTabs()
          break
        }

        /* ---- volumes ---- */
        case 'vol-copy': copyText(id); break
        case 'vol-remove': {
          if (el.getAttribute('data-used') === 'true') { toast('Volume is in use — detach it first', 'error'); break }
          state.volumes = state.volumes.filter(v => v.name !== id)
          toast('Volume removed: ' + id, 'success')
          renderResults(); renderTabs()
          break
        }
        case 'vol-prune': {
          const n = state.volumes.filter(v => !v.in_use).length
          state.volumes = state.volumes.filter(v => v.in_use)
          toast('Pruned ' + n + ' unused volume(s)', 'success')
          renderResults(); renderTabs()
          break
        }

        /* ---- stacks ---- */
        case 'open-svc': openDrawer(id, 'overview'); break
        case 'compose': {
          const op = el.getAttribute('data-op'), stack = el.getAttribute('data-stack')
          toast('docker compose -f ' + stack + '/docker-compose.yaml ' + op + ' (mocked)', 'info')
          break
        }
        case 'compose-logs':
          toast('Streaming compose logs for ' + el.getAttribute('data-stack') + ' (mocked)', 'info')
          break

        /* ---- modal ---- */
        case 'modal-cancel':
        case 'modal-close': closeModal(); break
        case 'modal-confirm': {
          const fn = state.modal && state.modal.onConfirm
          if (fn) fn()
          break
        }
        case 'run-submit': submitRun(); break

        /* ---- misc ---- */
        case 'copy': copyText(el.getAttribute('data-copy') || ''); break
      }
    }

    // central click delegation
    document.addEventListener('click', (ev) => {
      const menu = ev.target.closest('[data-menu]')
      if (menu) { /* clicks inside menu handled below */ }
      else if (state.menu) closeMenu()

      const el = ev.target.closest('[data-action]')
      if (el) {
        const action = el.getAttribute('data-action')
        // drawer-tab is handled separately via [data-drawer-tab]
        ev.preventDefault()
        handleAction(action, el)
        return
      }

      // open URL links
      const urlLink = ev.target.closest('[data-open-url]')
      if (urlLink) { ev.preventDefault(); toast('Opening in browser (mocked)', 'info'); return }

      // tabs (route)
      const tab = ev.target.closest('[data-route]')
      if (tab) { setRoute(tab.getAttribute('data-route')); return }

      // drawer tabs
      const dtab = ev.target.closest('[data-drawer-tab]')
      if (dtab) {
        state.drawerTab = dtab.getAttribute('data-drawer-tab')
        persistState()
        renderDrawer()
        if (state.drawerTab === 'logs' && !state.drawer.logs) loadLogs(state.selectedId)
        if (state.drawerTab === 'stats' && !state.drawer.stats) loadStats(state.selectedId)
        return
      }

      // row click → open drawer (ignore clicks on interactive cells)
      const tr = ev.target.closest('tr[data-id]')
      if (tr && !ev.target.closest('[data-actions]') && !ev.target.closest('input') && !ev.target.closest('a')) {
        // rows exist on containers table only
        if (ev.target.closest('table')) openDrawer(tr.getAttribute('data-id'), 'overview')
        return
      }

      // click outside modal backdrop closes (unless clicking the box)
      if (ev.target.matches('[data-modal-backdrop]')) closeModal()
    })

    // checkbox selection (change events)
    document.addEventListener('change', (ev) => {
      const t = ev.target

      if (t.id === 'auto-refresh') {
        state.autoRefresh = t.checked; persistState()
        if (state.autoRefresh) { startLive(); toast('Live updates on (polling every 3s)', 'info') }
        else { stopLive(); toast('Live updates paused', 'info') }
        return
      }
      if (t.id === 'host-select') { setHost(t.value); return }
      if (t.id === 'filter-state') { state.filters.state = t.value; persistState(); renderResults(); return }
      if (t.id === 'filter-stack') { state.filters.stack = t.value; persistState(); renderResults(); return }
      if (t.id === 'filter-sort') { state.filters.sort = t.value; persistState(); renderResults(); return }
      if (t.id === 'select-all') {
        const list = filteredList()
        state.selected = t.checked ? list.map(x => x.id) : []
        renderResults(); return
      }
      if (t.id === 'log-tail') { state.drawer.tail = Number(t.value); if (state.selectedId) loadLogs(state.selectedId); return }
      if (t.id === 'mock-fail') { state.__forceFail = t.checked; return }
      if (t.id === 'mock-empty') { state.__forceEmpty = t.checked; loadAll(); return }

      const chk = t.getAttribute && t.getAttribute('data-check')
      if (chk) { toggleSelect(chk, t.checked); return }

      const rf = t.getAttribute && t.getAttribute('data-run-field')
      if (rf && state.modal && state.modal.form) { state.modal.form[rf] = t.value; delete state.modal.errors[rf]; return }
    })

    // live search (partial re-render to preserve focus)
    document.addEventListener('input', (ev) => {
      const t = ev.target
      if (t.id === 'filter-q') { state.filters.q = t.value; persistState(); renderResults(); return }
      const rf = t.getAttribute && t.getAttribute('data-run-field')
      if (rf && state.modal && state.modal.form) {
        const caret = t.selectionStart
        state.modal.form[rf] = t.value
        delete state.modal.errors[rf]
        // update only the submit button + error, not the input (keeps focus)
        const errEl = t.parentElement.querySelector('.field-error')
        if (errEl) errEl.remove()
        t.classList.remove('invalid')
        void caret
      }
    })

    // refresh / run buttons
    document.addEventListener('click', (ev) => {
      if (ev.target.closest('#refresh-btn')) { toast('Refreshing…', 'info'); loadAll() }
      if (ev.target.closest('#run-btn')) openRunModal()
    })

    // keyboard
    document.addEventListener('keydown', (ev) => {
      if (ev.key === 'Escape') {
        if (state.modal) { closeModal(); return }
        if (state.menu) { closeMenu(); return }
        if (state.selectedId) closeDrawer()
      }
    })

    window.addEventListener('hashchange', () => {
      const r = (location.hash || '#/containers').replace('#/', '')
      if (r && r !== state.route && TABS.some(t => t.id === r)) {
        state.route = r
        state.selected = []
        persistState()
        renderTab()
      }
    })

    /* =======================================================================
       K. BOOT
       ======================================================================= */
    function boot() {
      // restore persisted UI state
      try {
        const saved = JSON.parse(localStorage.getItem(LS_KEY) || 'null')
        if (saved) {
          if (TABS.some(t => t.id === saved.route)) state.route = saved.route
          if (DB.hosts.some(h => h.id === saved.hostId)) state.hostId = saved.hostId
          state.autoRefresh = !!saved.autoRefresh
          if (saved.filters) state.filters = Object.assign(state.filters, saved.filters)
          state.selectedId = saved.selectedId || null
          state.drawerTab = saved.drawerTab || 'overview'
        }
      } catch (e) { /* ignore */ }

      // hash route wins over saved route
      const hashRoute = (location.hash || '').replace('#/', '').replace('#/', '')
      if (TABS.some(t => t.id === hashRoute)) state.route = hashRoute
      if (!location.hash) location.hash = '#/' + state.route

      restoreMutations()
      renderMockPanel()
      renderToasts()
      renderMenu()
      renderDrawer()
      renderModal()
      loadAll().then(() => {
        // restore drawer if a container was open before refresh
        if (state.selectedId && findContainer(state.selectedId)) openDrawer(state.selectedId, state.drawerTab)
        else state.selectedId = null
        if (state.autoRefresh) startLive()
      })
    }

    boot()
  })()
  </script>
</body>
</html>
