  { id: 'containers', label: 'Containers', icon: 'fa-cube' },
  { id: 'stacks', label: 'Stacks', icon: 'fa-layer-group' },
  { id: 'images', label: 'Images', icon: 'fa-box-archive' },
  { id: 'volumes', label: 'Volumes', icon: 'fa-database' },
